import type { DropTaskReview, TaskLifecycleOp } from "@shared/cards";
import { isSafeCardHref } from "@shared/linkify";
import { taskStatusWord } from "@shared/nowPanel";
import type { FrameTheme } from "@shared/plugins/frameDocument";
import type { TaskDetail } from "@shared/tasks";
import { presentTask } from "@shared/taskWaiting";
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { flushSync } from "react-dom";
import { type RecordAnchor, useShellStore } from "../app/store";
import { recordTemplate } from "../plugins/builtin";
import { BUILTIN_PLUGIN_ID } from "../plugins/builtin/manifest";
import { toneOf } from "../plugins/builtin/tasks/nowRows";
import { FrameMount } from "../plugins/frames/FrameMount";
import { pluginHost } from "../plugins/host";
import { appReadExecutor } from "../plugins/reads/appExecutor";
import { PANE_BOTTOM_MARGIN, PANE_MIN_TOP, panePlacement } from "./paneGeometry";
import { RecordPaneChrome, RecordPaneFooter } from "./RecordPaneChrome";
import { recordCanDrop, recordFooterOf, recordPillToneOf } from "./recordFooter";

/** The wire-less kind the built-in manifest dresses the record with. */
export const RECORD_CARD_KIND = "task-record";
/**
 * The record body's one declared action (audit A7): "Show the card" in its
 * waiting-on-you box. A pointing gesture - the host brings the task's
 * decision card forward (`focusCard`) and writes nothing.
 */
export const RECORD_SHOW_CARD_ACTION = "show-card";
/** The frame follows its document's height; the pane's own box does the clipping. */
const MAX_BODY_HEIGHT = 1_200;
const MIN_BODY_HEIGHT = 48;
/** The gap between the pane and the rail, which the tie spans. */
const TIE = 12;

/**
 * The task record as a PANE beside the now panel (task-system P4, revised
 * by the captain on the detail-pane prototype: "allow the task popover to
 * be wider, and remove the left border of the highlighted task row").
 *
 * It used to be the front entry of the centre card stack, which put the
 * detail in the middle of the window, over the character, in the same pager
 * as unrelated cards - far from the row it was opened from. Now it docks in
 * the right rail's gutter, anchored to that row: its top follows the row and
 * a hairline tie with a notch points at the row's centre, while the row
 * itself is selected inside the panel's frame (the shell pushes the
 * selection down as frame state, `fm.onState`). The placement arithmetic is
 * paneGeometry.ts.
 *
 * The chrome is the host's - status pill, task key with the model chip
 * beside it, title, and close - and so is the footer: Drop task on
 * never-started work, then Start, Stop it, or Continue, read off the task's
 * typed state. Merge, discard and keep stay on cards. Opening a filing
 * clears its new mark. The
 * body is the record template in the frame vehicle, fed by `tasks.detail`
 * over the bridge; its one action points at the task's decision card.
 * Never persisted, never agent-emitted, never a feed line.
 */
export function NowDetailPane({
  taskId,
  anchor,
  theme,
  onClose,
}: {
  taskId: string;
  anchor: RecordAnchor | null;
  theme: FrameTheme;
  onClose: () => void;
}) {
  const [detail, setDetail] = useState<TaskDetail | null>(null);
  const [unreadable, setUnreadable] = useState(false);
  const [modelLabels, setModelLabels] = useState<Record<string, string>>({});
  const template = useMemo(() => recordTemplate(taskId), [taskId]);
  const paneRef = useRef<HTMLElement>(null);
  const [placement, setPlacement] = useState(() => panePlacement(anchor, 0, window.innerHeight));
  const [bodyReadyTaskId, setBodyReadyTaskId] = useState<string | null>(null);
  const [positionedTaskId, setPositionedTaskId] = useState<string | null>(null);
  const topRef = useRef(placement.top);
  topRef.current = placement.top;

  useEffect(() => {
    let active = true;
    void window.firstmate.models
      .slots()
      .then((view) => {
        if (active) {
          setModelLabels(
            Object.fromEntries(view.models.map((m) => [`${m.provider}/${m.id}`, m.label])),
          );
        }
      })
      .catch(() => {});
    return () => {
      active = false;
    };
  }, []);

  useEffect(() => {
    setDetail(null);
    setUnreadable(false);
    return appReadExecutor().subscribe(
      "tasks.detail",
      { id: taskId },
      {
        onValue: (value) => setDetail(value as TaskDetail),
        onError: () => setUnreadable(true),
      },
    );
  }, [taskId]);

  useEffect(() => {
    if (!detail?.filing || !detail.filingNew) return;
    void window.firstmate.tasks.opened(taskId).catch(() => {});
  }, [taskId, detail?.filing, detail?.filingNew]);

  useEffect(() => {
    const closeOutside = (event: PointerEvent) => {
      if (!paneRef.current?.contains(event.target as Node)) onClose();
    };
    document.addEventListener("pointerdown", closeOutside, true);
    return () => document.removeEventListener("pointerdown", closeOutside, true);
  }, [onClose]);

  // The pane is placed against its own measured height, so the clamp knows
  // the real box: re-measure whenever the anchor moves, the body grows (the
  // record's sections land over the bridge), or the window resizes.
  useLayoutEffect(() => {
    const place = () => {
      const height = paneRef.current?.offsetHeight ?? 0;
      setPlacement(panePlacement(anchor, height, window.innerHeight, topRef.current));
    };
    place();
    // Reveal only after the populated frame has supplied its full height.
