          position: "absolute",
          right: -5,
          top: placement.notchY - 5,
          width: 9,
          height: 9,
          transform: "rotate(45deg)",
          background: "var(--acrylic-bg)",
          backdropFilter: "var(--acrylic-blur)",
          WebkitBackdropFilter: "var(--acrylic-blur)",
          borderTop: "1px solid var(--accent-glow)",
          borderRight: "1px solid var(--accent-glow)",
          opacity: placement.tied ? 1 : 0,
        }}
      />
