        status={detail ? taskStatusWord(detail) : "loading"}
        pillTone={detail ? recordPillToneOf(detail) : "neutral"}
        dotTone={detail ? toneOf(detail) : null}
        taskKey={meta || null}
        model={model}
        title={detail?.title ?? ""}
        onClose={onClose}
      />
      <div
        data-record-card={taskId}
        style={{ flex: 1, minHeight: 0, overflowY: "auto", padding: "10px 16px 16px" }}
      >
        <FrameMount
          key={taskId}
          onMountError={() => setUnreadable(true)}
          title="Task record body"
          template={template}
          spec={{
            pluginId: BUILTIN_PLUGIN_ID,
            reads: pluginHost.declaredReads(BUILTIN_PLUGIN_ID),
            grant: pluginHost.grantOf(BUILTIN_PLUGIN_ID),
            actions: [RECORD_SHOW_CARD_ACTION],
            // The template is zero-height until it has content (or an error).
            onResize: (height) => {
              if (height > 0) setBodyReadyTaskId(taskId);
            },
            onAction: (actionId) => {
              if (actionId === RECORD_SHOW_CARD_ACTION) showCard();
            },
            onLink: (href) => {
              if (isSafeCardHref(href)) {
                void window.firstmate.app.openExternal(href).catch(() => {});
              }
            },
          }}
          theme={theme}
          layout="auto"
          minAutoHeight={MIN_BODY_HEIGHT}
          maxAutoHeight={MAX_BODY_HEIGHT}
        />
      </div>
      {detail && (
        <RecordPaneFooter
          footer={recordFooterOf(detail)}
          canDrop={recordCanDrop(detail)}
          effects={detail.dropEffects ?? null}
          taskKey={detail.key}
          revision={detail}
          onRun={runOp}
        />
      )}
    </aside>
  );
}

