import type { DropTaskReview, TaskLifecycleOp } from "@shared/cards";
import {
  DROP_CANCEL_LABEL,
  DROP_REVIEW_STALE,
  DROP_TASK_LABEL,
  dropConfirmLead,
  dropPartsRefusal,
  dropUnderwayLine,
  dropWaitingLine,
  HIDE_RECORD_LABEL,
} from "@shared/recordDrop";
import type { DropEffects } from "@shared/tasks";
import type React from "react";
import { useEffect, useState } from "react";
import { Badge, Button, IconButton } from "../design";
import { ModelChip } from "../design/core/ModelChip";
import type { RecordFooter, RecordPillTone } from "./recordFooter";

const closeIcon = (
  <svg
    width="16"
    height="16"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth={1.5}
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
  >
    <path d="M18 6 6 18M6 6l12 12" />
  </svg>
);

/** The Tasks rail's dot tones (`toneOf`), painted the way the rail paints them. */
export type RecordDotTone = "ring" | "ok" | "warn" | "danger";

const dotFills: Record<RecordDotTone, React.CSSProperties> = {
  ring: { background: "transparent", border: "1px solid var(--fg-2)" },
  ok: { background: "var(--ok)" },
  warn: { background: "var(--warn)" },
  danger: { background: "var(--danger)" },
};

const keyText: React.CSSProperties = {
  fontFamily: "var(--font-mono)",
  fontSize: "var(--text-xs)",
  fontWeight: 400,
  letterSpacing: "normal",
  color: "var(--fg-3)",
  whiteSpace: "nowrap",
  overflow: "hidden",
  textOverflow: "ellipsis",
  minWidth: 0,
};

/**
 * Host chrome for the task record pane. The status pill, the task key, and
 * the assigned model share the top row: the pill's dot is the Tasks rail's
 * own dot for the task, the key gives way when the row is tight, and the
 * model is its chip beside the key - never truncated, never pushed out.
 * The title sits alone beneath, at the decision card's title size.
 */
export function RecordPaneChrome({
  status,
  pillTone,
  dotTone,
  taskKey,
  model,
  title,
  onClose,
}: {
  status: string;
  pillTone: RecordPillTone;
  /** The rail's dot for this task (`toneOf`); null while the record loads. */
  dotTone: RecordDotTone | null;
  taskKey: string | null;
  model: string | null;
  title: string;
  onClose: () => void;
}) {
  return (
    <>
      <div
        data-record-chrome=""
        style={{
          display: "flex",
          alignItems: "center",
          gap: 10,
          padding: "12px 10px 0 16px",
          flexShrink: 0,
          minWidth: 0,
        }}
      >
        <span data-record-status={pillTone} style={{ display: "inline-flex", flexShrink: 0 }}>
          <Badge tone={pillTone} dot={pillTone !== "neutral" || !dotTone}>
            {pillTone === "neutral" && dotTone && (
              <span
                aria-hidden="true"
                data-record-dot={dotTone}
                style={{
                  width: 5,
                  height: 5,
                  borderRadius: "50%",
                  boxSizing: "border-box",
                  flexShrink: 0,
                  ...dotFills[dotTone],
                }}
              />
            )}
            {status}
          </Badge>
        </span>
        {(taskKey || model) && (
          // A model chip with no room beside the key takes the next line
          // of the top row, whole, rather than leaving the pane.
          <span
            data-record-identity=""
            style={{
              display: "flex",
              flexWrap: "wrap",
              alignItems: "center",
              gap: "var(--space-1) var(--space-2)",
              minWidth: 0,
              flex: 1,
            }}
          >
            {taskKey && (
              <span data-record-key="" title={taskKey} style={keyText}>
                {taskKey}
              </span>
            )}
            {model && (
              <span
                data-record-model=""
                style={{ display: "inline-flex", flexShrink: 0, minWidth: 0, maxWidth: "100%" }}
              >
                <ModelChip label={model} />
              </span>
            )}
          </span>
        )}
        <IconButton
          label={HIDE_RECORD_LABEL}
          onClick={onClose}
          style={{ marginLeft: "auto", flexShrink: 0 }}
        >
          {closeIcon}
        </IconButton>
      </div>
      <div
        data-record-title=""
        style={{
          padding: "8px 16px 0",
          fontSize: "var(--text-lg)",
          fontWeight: 500,
          letterSpacing: "var(--tracking-display)",
          color: "var(--fg-1)",
          lineHeight: "var(--leading-tight)",
        }}
      >
        {title}
      </div>
    </>
  );
}

/**
 * The record's footer: the host's own buttons, driven only by the task's
 * typed state, right-aligned, the one primary last.
 *
 * Stop it and Drop task each ask once, inline. Cancel restores the footer
 * and writes nothing. A click is pending until the record changes; competing
 * buttons disable immediately. A refusal is an inline error and writes nothing.
 * Enter does not approve a drop: Cancel takes focus, and both buttons are
 * type="button".
 */
export function RecordPaneFooter({
  footer,
  canDrop,
  effects,
  taskKey,
  revision,
  onRun,
}: {
  footer: RecordFooter;
  canDrop: boolean;
  effects: DropEffects | null;
  taskKey: string;
  /** Changes whenever the record does: a pending click clears on it. */
  revision: unknown;
  onRun: (op: TaskLifecycleOp, review?: DropTaskReview) => Promise<unknown>;
}) {
  const [confirming, setConfirming] = useState(false);
  const [confirmingDrop, setConfirmingDrop] = useState(false);
  const [pending, setPending] = useState<TaskLifecycleOp | null>(null);
  const [error, setError] = useState<string | null>(null);
  const reviewKey = effects ? JSON.stringify(effects) : "";

  // A new reading of the record settles whatever was in flight.
  // biome-ignore lint/correctness/useExhaustiveDependencies: `revision` is the trigger.
  useEffect(() => {
    setPending(null);
  }, [revision]);
  // biome-ignore lint/correctness/useExhaustiveDependencies: kind, task and reviewed effects are the triggers.
  useEffect(() => {
    setConfirming(false);
    setConfirmingDrop(false);
    setError(null);
  }, [footer.kind, taskKey, reviewKey]);

  if (footer.kind === "none" && !canDrop) return null;

  const run = (op: TaskLifecycleOp, review?: DropTaskReview) => {
    setPending(op);
    setError(null);
    onRun(op, review).catch((caught: unknown) => {
      setPending(null);
      setConfirmingDrop(false);
      setError(caught instanceof Error ? caught.message : String(caught));
    });
  };
  const busy = pending !== null;
  const beginDrop = () => {
    if (!effects) {
      setError(DROP_REVIEW_STALE);
      return;
    }
    if (effects.parts.length > 0) {
      setError(dropPartsRefusal(taskKey, effects.parts));
      return;
    }
    setError(null);
    setConfirmingDrop(true);
  };

  let lead: React.ReactNode = null;
  let buttons: React.ReactNode;
  let footerKind = footer.kind === "none" ? "drop" : footer.kind;
  if (confirmingDrop && effects) {
    footerKind = "drop-confirm";
    const waiting = dropWaitingLine(effects.waiting);
    const underway = dropUnderwayLine(effects.underway);
    lead = (
      <span
        data-record-confirm="drop"
        style={{
          fontSize: "var(--text-sm)",
          color: "var(--fg-2)",
          minWidth: 0,
          whiteSpace: "normal",
        }}
      >
        {dropConfirmLead(taskKey)}
        {waiting ? ` ${waiting}` : ""}
        {underway ? ` ${underway}` : ""}
      </span>
    );
    buttons = (
      <>
        <Button
          variant="secondary"
          autoFocus
          disabled={busy}
          data-record-action="cancel"
          onClick={() => setConfirmingDrop(false)}
        >
