import type { RecordAnchor } from "../app/store";

/**
 * Where the task-record pane sits, and where it points (task-system P4, the
 * captain's detail-pane call). The pane docks in the right rail's gutter and
 * anchors to the row it was opened from: its top follows the row, and a tie
 * on its right edge points at the row's centre.
 *
 * The arithmetic is here, away from the DOM, because it is the whole of the
 * behaviour worth pinning: a row near the bottom of a tall panel must not
 * push the pane off the window, the tie must keep pointing at the row after
 * that clamp, and a row scrolled out of the panel's own viewport must leave
 * the pane where it is rather than drag it along.
 */

/** Clear of the 52px top bar, so the pane's close is never under the drag region. */
export const PANE_MIN_TOP = 60;
/** The gap the pane keeps from the bottom of the window. */
export const PANE_BOTTOM_MARGIN = 16;
/** How far above the row's top edge the pane starts, so the two read as one. */
export const PANE_LIFT = 8;
/** How close to the pane's own corners the tie may point. */
export const PANE_NOTCH_INSET = 14;

export type PanePlacement = {
  /** Window coordinates, clamped to the window. */
  top: number;
  /** Where the tie meets the pane, measured from the pane's own top. */
  notchY: number;
  /** False when the pane has no row to point at and drops the tie. */
  tied: boolean;
};

export function panePlacement(
  anchor: RecordAnchor | null,
  paneHeight: number,
  windowHeight: number,
  previousTop?: number,
): PanePlacement {
  // No row to point at: hold the last position (or the top of the gutter on
  // a first paint) and untie, so nothing jumps and nothing lies.
  if (!anchor) {
    return { top: previousTop ?? PANE_MIN_TOP, notchY: PANE_NOTCH_INSET, tied: false };
  }
  const lowest = Math.max(PANE_MIN_TOP, windowHeight - paneHeight - PANE_BOTTOM_MARGIN);
  const top = Math.min(Math.max(anchor.top - PANE_LIFT, PANE_MIN_TOP), lowest);
  const centre = anchor.top + anchor.height / 2;
  const reach = Math.max(PANE_NOTCH_INSET, paneHeight - PANE_NOTCH_INSET);
  const notchY = Math.min(Math.max(centre - top, PANE_NOTCH_INSET), reach);
  return { top, notchY, tied: true };
}

/**
 * The row's box as the host sees it: what the panel's frame measured in its
 * own viewport, plus where that frame sits in the window. A report with no
 * row (the row scrolled out of the panel's viewport) stays null.
 */
export function anchorInWindow(
  reported: { top: number; height: number } | null,
  frame: DOMRect | undefined,
): RecordAnchor | null {
  if (!reported) return null;
  return { top: reported.top + (frame?.top ?? 0), height: reported.height };
}
import { nowGroupOf } from "@shared/nowPanel";
import { isUnstartedWork, type TaskView } from "@shared/tasks";

/**
 * What the task record's footer offers, read only from typed fields of
 * the task, never from its prose. Start, stop and continue are the
 * captain's 4A (2026-09-28). Drop task is the later choice for
 * never-started work (FI3-243): it sits beside Start, or alone when Start
 * does not apply. Merge, discard and keep stay on cards.
 *
 * - `start`: charted work that waits for the captain's word (on request,
 *   no parts of its own). With blockers it is offered disabled, naming
 *   what it waits on.
 * - `stop`: a crewmate is on it, working or idle.
 * - `resume`: the crewmate was interrupted; Continue, or Stop it.
 * - `none`: a parent whose parts do the work, a task a decision card
 *   waits on (the card is where the captain answers), when-ready work,
 *   and closed work. Drop task may still apply (`recordCanDrop`).
 */
export type RecordFooter =
  | { kind: "none" }
  | { kind: "start"; waitsOn: readonly string[]; blocked?: true }
  | { kind: "stop" }
  | { kind: "resume" };

export function recordFooterOf(task: TaskView): RecordFooter {
  if (task.kind !== "work" || task.waitingCardId) return { kind: "none" };
  if (task.status === "open") {
    if (task.children.total > 0) return { kind: "none" };
    if (task.blockedBy.length > 0) return { kind: "start", waitsOn: task.blockedBy };
    // A dropped dependency is no longer live work to name, but its edge still
    // needs Firstmate's decision before dispatch (docs/task-graph.md).
    if (task.flags.blocked) return { kind: "start", waitsOn: [], blocked: true };
    return task.startPolicy === "on-request" ? { kind: "start", waitsOn: [] } : { kind: "none" };
  }
  if (task.status === "active") {
    return task.activity === "interrupted" ? { kind: "resume" } : { kind: "stop" };
  }
  return { kind: "none" };
}

/** Drop task on open work that has never started, including parents and blocked rows. */
export function recordCanDrop(task: TaskView): boolean {
  return isUnstartedWork(task);
}

/**
 * The status pill's tint (audit A1). Its dot is the Tasks rail's (`toneOf`);
 * the whole pill tints only when the state needs the captain's eye: waiting
 * on you in the accent, interrupted or failed in danger. Every other state
 * is the neutral pill.
 */
export type RecordPillTone = "neutral" | "accent" | "danger";

export function recordPillToneOf(task: TaskView): RecordPillTone {
  if (nowGroupOf(task) === "waiting") return "accent";
  if (task.closedReason === "failed") return "danger";
  if (task.status === "active" && task.activity === "interrupted") return "danger";
  return "neutral";
}

