      <>
        <Button
          variant="secondary"
          autoFocus
          disabled={busy}
          data-record-action="cancel"
          onClick={() => setConfirmingDrop(false)}
        >
          {DROP_CANCEL_LABEL}
        </Button>
        <Button
          variant="danger"
          pending={pending === "drop-task"}
          disabled={busy}
          data-record-action="confirm-drop"
          onClick={() =>
            run("drop-task", {
              parts: effects.parts.map((part) => part.key),
              waiting: effects.waiting.map((task) => task.key),
              underway: effects.underway.map((task) => task.key),
            })
          }
        >
          {DROP_TASK_LABEL}
        </Button>
      </>
    );
  } else if (confirming) {
    footerKind = "confirm";
    lead = (
      <span
        data-record-confirm="stop"
        style={{ fontSize: "var(--text-sm)", color: "var(--fg-2)", minWidth: 0 }}
      >
        {`Stop ${taskKey}? It ends the task and keeps a copy of its unfinished work.`}
      </span>
    );
    buttons = (
      <>
        <Button variant="secondary" disabled={busy} onClick={() => setConfirming(false)}>
          Cancel
        </Button>
        <Button
          variant="primary"
          pending={pending === "stop-task"}
          disabled={busy}
          onClick={() => run("stop-task")}
        >
          Stop it
        </Button>
      </>
    );
  } else if (footer.kind === "start" || footer.kind === "none") {
    const blocked =
      footer.kind === "start" && (footer.waitsOn.length > 0 || footer.blocked === true);
    if (blocked) {
