        <span
          data-record-waits=""
          style={{ fontSize: "var(--text-sm)", color: "var(--fg-3)", minWidth: 0 }}
        >
          {footer.waitsOn.length > 0
            ? `Waits on ${footer.waitsOn.join(", ")}`
            : "Ask Firstmate about its dependencies before starting."}
        </span>
      );
    }
    buttons = (
      <>
        {canDrop && (
          <Button variant="secondary" disabled={busy} onClick={beginDrop}>
            {DROP_TASK_LABEL}
          </Button>
        )}
        {footer.kind === "start" && (
          <Button
            variant="primary"
            pending={pending === "start-task"}
            disabled={blocked || busy}
            onClick={() => run("start-task")}
          >
            Start
          </Button>
        )}
      </>
    );
  } else {
    buttons = (
      <>
        <Button variant="secondary" disabled={busy} onClick={() => setConfirming(true)}>
          Stop it
        </Button>
        {footer.kind === "resume" && (
          <Button
            variant="primary"
            pending={pending === "continue-task"}
            disabled={busy}
            onClick={() => run("continue-task")}
          >
            Continue
          </Button>
        )}
      </>
    );
  }

  return (
    <div
      data-record-footer={footerKind}
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--space-2)",
        padding: "var(--space-3) var(--space-4) var(--space-4)",
        flexShrink: 0,
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "flex-end",
          flexWrap: "wrap",
          gap: "var(--space-2)",
        }}
      >
        {lead && <div style={{ marginRight: "auto", minWidth: 0, flex: "1 1 auto" }}>{lead}</div>}
        {buttons}
      </div>
      {error && (
        <p role="alert" style={{ margin: 0, color: "var(--danger)", fontSize: "var(--text-sm)" }}>
          {error}
        </p>
      )}
    </div>
  );
}
