    return task.startPolicy === "on-request" ? { kind: "start", waitsOn: [] } : { kind: "none" };
  }
  if (task.status === "active") {
    return task.activity === "interrupted" ? { kind: "resume" } : { kind: "stop" };
  }
  return { kind: "none" };
}

/** Drop task on open work that has never started, including parents and blocked rows. */
export function recordCanDrop(task: TaskView): boolean {
  return isUnstartedWork(task);
}

/**
 * The status pill's tint (audit A1). Its dot is the Tasks rail's (`toneOf`);
 * the whole pill tints only when the state needs the captain's eye: waiting
 * on you in the accent, interrupted or failed in danger. Every other state
 * is the neutral pill.
 */
export type RecordPillTone = "neutral" | "accent" | "danger";

export function recordPillToneOf(task: TaskView): RecordPillTone {
  if (nowGroupOf(task) === "waiting") return "accent";
  if (task.closedReason === "failed") return "danger";
  if (task.status === "active" && task.activity === "interrupted") return "danger";
  return "neutral";
}

