import type React from "react";
import { Badge, type BadgeTone } from "../core/Badge";
import { IconButton } from "../core/IconButton";
import { ModelChip } from "../core/ModelChip";

/**
 * The chrome a card wears, derived from what it is and never declared on
 * the wire (cards/tasks/agents P1, ruling D1 a): `decision` has actions,
 * `note` has none, `attention` is the host's own (the agent-down set);
 * `working` is a card mid-revision and `record` a task's record.
 */
export type ResponseCardKind = "decision" | "note" | "attention" | "working" | "record";

export type ResponseCardProps = {
  kind?: ResponseCardKind;
  title?: string;
  /** Mono metadata line: relative time, crewmate ref. */
  meta?: string;
  /**
   * The model its author ran on: an outline mono chip right after the meta
   * line, which gives way to it (the chip is never truncated or pushed out).
   */
  model?: string;
  /** Action button row (app-owned chrome), right-aligned. */
  actions?: React.ReactNode;
  /** Top-right chrome close; not a declared card action. */
  onClose?: () => void;
  children?: React.ReactNode;
  width?: number | string;
  minHeight?: number;
  /**
   * Whether the card draws its own surface. False when it is one COLUMN of
   * a larger container - a card with its thread open beside it, which is one
   * acrylic surface, one border, one radius and one shadow for the pair
   * (design skill `components/cards/CardThread.prompt.md`). The card's own
   * height cap goes with it: the container caps the pair.
   */
  surface?: boolean;
  /** Extra chrome in the head, between the badge and the meta line. */
  headExtra?: React.ReactNode;
  /**
   * Host chrome below the action row - the card's reply row while it has no
   * thread yet (design skill `components/cards/CardThread.prompt.md`). It is
   * never a card action and never wraps into that row.
   */
  footer?: React.ReactNode;
  style?: React.CSSProperties;
};

const closeIcon = (
  <svg
    width="16"
    height="16"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth={1.5}
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
  >
    <path d="M18 6 6 18M6 6l12 12" />
  </svg>
);

const cardKinds: Record<ResponseCardKind, { label: string; tone: BadgeTone }> = {
  decision: { label: "Decision", tone: "accent" },
  note: { label: "Note", tone: "neutral" },
  attention: { label: "Attention", tone: "danger" },
  working: { label: "Working", tone: "accent" },
  /** A task's record (task-system P4): never any card actions; its footer is the host's. */
  record: { label: "Task", tone: "neutral" },
};

/**
 * The tallest a card on the stage may be. The stack is centred 60px above
 * the stage's middle and carries a pager under the card; at the shortest
 * window (640px) this keeps the card's top clear of the 52px top bar, so
 * close is never under the drag region. The composer's growth
 * (`--prompt-rise`) comes off it, so the air between a tall card and a
 * multi-line input never closes (docs/composer.md). A taller body scrolls
 * inside the card.
 */
export const CARD_MAX_HEIGHT = "calc(100vh - 3 * var(--space-9) - var(--prompt-rise))";

export function ResponseCard({
  kind = "note",
  title,
  meta,
  model,
  actions,
  onClose,
  children,
  width = 560,
  minHeight = 340,
  surface = true,
  headExtra,
  footer,
  style,
}: ResponseCardProps) {
  const k = cardKinds[kind] || cardKinds.note;
  return (
    <div
      style={{
        width,
        // The floor gives way to the cap (CARD_MAX_HEIGHT) when a tall
        // composer shrinks it, here and as one column of the pair.
        minHeight: `min(${minHeight}px, ${CARD_MAX_HEIGHT})`,
        ...(surface
          ? {
              maxHeight: CARD_MAX_HEIGHT,
              background: "var(--acrylic-bg)",
              backdropFilter: "var(--acrylic-blur)",
              WebkitBackdropFilter: "var(--acrylic-blur)",
              border: "1px solid var(--acrylic-border)",
              borderRadius: "var(--radius-l)",
              boxShadow: "var(--acrylic-shadow)",
            }
          : { minWidth: 0 }),
        boxSizing: "border-box",
        display: "flex",
        flexDirection: "column",
        overflow: "hidden",
        ...style,
      }}
    >
      <div
        data-card-head=""
        style={{ display: "flex", alignItems: "center", gap: 10, padding: "14px 12px 0 20px" }}
      >
        <Badge tone={k.tone} dot style={{ flexShrink: 0 }}>
          {k.label}
        </Badge>
        {headExtra}
        {(meta || model) && (
          // The meta line and the model chip share the room between the
          // chip and close. A long meta line (crewmate ref carrying a repo
          // name) truncates with an ellipsis instead of wrapping the card
          // header, and it is the one that gives way: the chip keeps its
          // whole name, wrapping inside itself only when the name is longer
          // than all the room there is.
          <span
            style={{
              display: "flex",
              alignItems: "center",
              gap: 10,
              minWidth: 0,
              flex: 1,
            }}
          >
            {meta && (
              <span
                data-card-meta=""
                style={{
                  fontFamily: "var(--font-mono)",
                  fontSize: "var(--text-xs)",
                  color: "var(--fg-3)",
                  whiteSpace: "nowrap",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                  minWidth: 0,
                  flex: model ? "0 1 auto" : 1,
                }}
              >
                {meta}
              </span>
            )}
            {model && <ModelChip label={model} />}
          </span>
        )}
        <IconButton label="Close" onClick={onClose} style={{ marginLeft: "auto", flexShrink: 0 }}>
          {closeIcon}
        </IconButton>
      </div>
      {title && (
        <div
          style={{
            padding: "10px 20px 0",
            fontSize: "var(--text-lg)",
            fontWeight: 500,
            letterSpacing: "var(--tracking-display)",
            color: "var(--fg-1)",
            lineHeight: "var(--leading-tight)",
          }}
        >
          {title}
        </div>
      )}
      <div
        data-card-body=""
        style={{
          flex: 1,
          minHeight: 0,
          // Keep the frame's width independent of overflow: a scrollbar that
          // takes width shrinks fluid content, whose height report can remove
          // that same scrollbar and start an endless resize feedback loop.
          overflowY: "auto",
          scrollbarGutter: "stable",
          padding: "12px 20px 18px",
          fontSize: "var(--text-base)",
          color: "var(--fg-2)",
          lineHeight: "var(--leading-body)",
        }}
      >
        {children}
      </div>
      {actions && (
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            justifyContent: "flex-end",
            gap: "var(--space-2)",
            rowGap: "var(--space-2)",
            // Keep the body separate from its choices and keep air above the
            // footer's hairline.
            padding: footer ? "var(--space-3) 16px var(--space-3)" : "var(--space-3) 16px 16px",
          }}
        >
          {actions}
        </div>
      )}
      {footer && <div style={{ padding: "0 16px 16px", flexShrink: 0 }}>{footer}</div>}
    </div>
  );
}
import type React from "react";
import { Badge } from "../core/Badge";
import { IconButton } from "../core/IconButton";

const csIcoS = {
  fill: "none",
  stroke: "currentColor",
  strokeWidth: 1.5,
  strokeLinecap: "round",
  strokeLinejoin: "round",
} as const;

/** The stack's design width; the stage narrows it on a narrow window. */
export const CARD_STACK_WIDTH = 560;

/** The unread dot on an arrow that leads to an unseen card (design skill CardStack). */
const unreadDot: React.CSSProperties = {
  position: "absolute",
  top: 6,
  right: 6,
  width: 6,
  height: 6,
  borderRadius: "var(--radius-pill)",
  background: "var(--accent)",
  boxShadow: "0 0 0 2px var(--bg-0)",
  pointerEvents: "none",
};

export type CardStackProps = {
  index?: number;
  count?: number;
  /** Unseen cards before the shown one: a dot on "Previous card". */
  unreadBefore?: number;
  /** Unseen cards after the shown one: a dot on "Next card". */
  unreadAfter?: number;
  onPrev?: () => void;
  onNext?: () => void;
  width?: number | string;
  children?: React.ReactNode;
  peekStyle?: React.CSSProperties;
  style?: React.CSSProperties;
};

export function CardStack({
  index = 0,
  count = 1,
  unreadBefore = 0,
  unreadAfter = 0,
  onPrev,
  onNext,
  width = CARD_STACK_WIDTH,
  children,
  peekStyle,
  style,
}: CardStackProps) {
  const peekBase: React.CSSProperties = {
    position: "absolute",
    background: "var(--acrylic-bg)",
    backdropFilter: "var(--acrylic-blur)",
    WebkitBackdropFilter: "var(--acrylic-blur)",
    border: "1px solid var(--acrylic-border)",
    borderBottom: "none",
    borderRadius: "var(--radius-l) var(--radius-l) 0 0",
    height: 14,
  };
  const unread = unreadBefore + unreadAfter;
  return (
    <div style={{ position: "relative", width, ...style }}>
      {count > 2 && (
        <div style={{ ...peekBase, left: 14, right: 14, top: -14, ...peekStyle, opacity: 0.35 }} />
      )}
      {count > 1 && (
        <div style={{ ...peekBase, left: 7, right: 7, top: -7, ...peekStyle, opacity: 0.65 }} />
      )}
      <div style={{ position: "relative" }}>{children}</div>
      {count > 1 && (
        <div style={{ display: "flex", justifyContent: "center", marginTop: 10 }}>
          <div style={{ position: "relative", display: "flex", alignItems: "center", gap: 6 }}>
            <span style={{ position: "relative", display: "inline-flex" }}>
              <IconButton label="Previous card" size={28} onClick={onPrev} disabled={index <= 0}>
                <svg width="14" height="14" viewBox="0 0 24 24" {...csIcoS} aria-hidden="true">
                  <path d="m15 18-6-6 6-6" />
                </svg>
              </IconButton>
              {unreadBefore > 0 && <span data-unread-dot="before" style={unreadDot} />}
            </span>
            <span
              style={{
                fontFamily: "var(--font-mono)",
                fontSize: "var(--text-xs)",
                color: "var(--fg-3)",
              }}
            >
              {index + 1} / {count}
            </span>
            <span style={{ position: "relative", display: "inline-flex" }}>
              <IconButton
                label="Next card"
                size={28}
                onClick={onNext}
                disabled={index >= count - 1}
              >
                <svg width="14" height="14" viewBox="0 0 24 24" {...csIcoS} aria-hidden="true">
                  <path d="m9 18 6-6-6-6" />
                </svg>
              </IconButton>
              {unreadAfter > 0 && <span data-unread-dot="after" style={unreadDot} />}
            </span>
            {unread > 0 && (
              // Outside the centred arrow group's flow, so the arrows never
              // move under the pointer as the badge comes and goes.
              <span
                role="status"
                style={{
                  position: "absolute",
                  left: "100%",
                  marginLeft: "var(--space-2)",
                  whiteSpace: "nowrap",
                }}
              >
                <Badge tone="accent" mono>
                  {unread} new
                </Badge>
              </span>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
/* Firstmate 3000 — radii, shadows, glow, blur, motion. */
:root {
  --radius-xs: 3px; /* small controls: a 14-16px box that must read square, not round */
  --radius-s: 6px; /* badges, keycaps */
  --radius-m: 10px; /* buttons, inputs */
  --radius-l: 16px; /* cards, panels */
  --radius-pill: 999px; /* voice input shell, pills */
  --shadow-1: 0 1px 2px rgba(0, 0, 0, 0.35);
  --shadow-2: 0 8px 30px -12px rgba(0, 0, 0, 0.6);
  --shadow-card: 0 12px 40px -16px rgba(0, 0, 0, 0.65), 0 1px 0 rgba(150, 180, 255, 0.06) inset;
  --glow-accent: 0 0 32px -8px var(--accent-glow);
  /* acrylic — the card material (variant A "frosted") */
  --acrylic-bg: rgba(255, 255, 255, 0.06);
  --acrylic-blur: blur(20px); /* @kind other */
  --acrylic-border: rgba(255, 255, 255, 0.1);
  --acrylic-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.1), 0 24px 48px -24px rgba(0, 0, 0, 0.6);
  --blur-overlay: blur(16px); /* @kind other */
  /* motion — slow, drifting, never bouncy */
  --ease-drift: cubic-bezier(0.25, 0.1, 0.25, 1); /* @kind other */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1); /* @kind other */
  --dur-fast: 160ms; /* @kind other */
  --dur-med: 360ms; /* @kind other */
  --dur-slow: 700ms; /* @kind other */
}
[data-theme="light"] {
  --shadow-1: 0 1px 2px rgba(20, 30, 60, 0.1);
  --shadow-2: 0 8px 30px -12px rgba(20, 30, 60, 0.18);
  --shadow-card: 0 12px 40px -16px rgba(20, 30, 60, 0.22);
  --acrylic-bg: rgba(255, 255, 255, 0.4);
  --acrylic-blur: blur(24px) saturate(1.8); /* @kind other */
  --acrylic-border: rgba(20, 30, 60, 0.14);
  --acrylic-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 12px 32px -12px rgba(20, 30, 60, 0.28),
    0 2px 8px -2px rgba(20, 30, 60, 0.1);
}
/* Firstmate 3000 — color system. Dark ("deep space") is the default theme; light opts in via [data-theme="light"]. */
:root {
  /* base */
  --bg-0: #05070d; /* void — the opaque fallback behind --material-tint */
  --material-tint: rgba(5, 7, 13, 1); /* opaque tint mixed toward clear by wash percentage */
  --bg-1: #0a0e18; /* surface — panels, input shell */
  --bg-2: #0f1424; /* raised — cards */
  --bg-3: #161c30; /* overlay hover */
  --line-1: rgba(150, 180, 255, 0.2); /* hairline borders, set for the material */
  --line-2: rgba(150, 180, 255, 0.24); /* focused / active borders */
  --fg-1: #e9eef8; /* primary text */
  --fg-2: #98a4bd; /* secondary text */
  --fg-3: #7a86a0; /* tertiary / placeholder, lifted for the material */
  /* accent — ice cyan, the Firstmate's light */
  --accent: #7fdcff;
  --accent-strong: #38aae6;
  --accent-dim: rgba(127, 220, 255, 0.14);
  --accent-glow: rgba(127, 220, 255, 0.35);
  /* semantic — two chromatic families only: ice cyan (calm) and ember (hot) */
  --ok: #7fdcff; /* calm cyan — done, pace ahead (same family as accent) */
  --ok-dim: rgba(127, 220, 255, 0.14);
  --hot: #ffa257; /* ember — the one hot color: energy, sun, fire */
  --hot-dim: rgba(255, 162, 87, 0.14);
  --hot-glow: rgba(255, 148, 66, 0.35);
  --warn: #ffa257; /* attention, pace behind — ember */
  --warn-dim: rgba(255, 162, 87, 0.14);
  --danger: #ff6b52; /* lava — errors, exhausted quota (hot family, redder) */
  --danger-dim: rgba(255, 107, 82, 0.12);
  --captain: #b99aff; /* violet — the captain's own activity */
  --captain-dim: rgba(185, 154, 255, 0.14);
  --idle: #5d6884; /* dormant crewmates, inactive */
  /* intelligence slots - celestial: supernova (lava) / sun / earth / moon.
     supernova sits above the sun and is the one slot the app never reaches
     for on its own. --bucket-* aliases keep older mocks working. */
  --slot-premium: #ff6b52;
  --slot-high: #ffa257;
  --slot-medium: #7fdcff;
  --slot-low: #8a93a8;
  --bucket-premium: var(--slot-premium);
  --bucket-high: var(--slot-high);
  --bucket-medium: var(--slot-medium);
  --bucket-low: var(--slot-low);
  /* wireframe characters (canvas) */
  --wire-accent: #7fdcff;
  --wire-hot: #ffa257;
  --wire-dim: #2e6a8c; /* far side — same cyan family, darker */
  --wire-boost: 1; /* @kind other */ /* alpha multiplier — raised in light theme where thin lines wash out */
  --halo-boost: 1.2; /* @kind other */ /* the Firstmate's halo, lifted so it reads over the material */
  color-scheme: dark;
}
[data-theme="light"] {
  --bg-0: #eef1f7;
  --material-tint: rgba(238, 241, 247, 1);
  --bg-1: #f7f9fc;
  --bg-2: #ffffff;
  --bg-3: #e7ecf5;
  --line-1: rgba(30, 50, 90, 0.18);
  --line-2: rgba(30, 50, 90, 0.26);
  --fg-1: #151b2b;
  --fg-2: #4d5a75;
  --fg-3: #6c7891;
  --accent: #0e8fd0;
  --accent-strong: #0a72a8;
  --accent-dim: rgba(14, 143, 208, 0.1);
  --accent-glow: rgba(14, 143, 208, 0.25);
  --ok: #0e8fd0;
  --ok-dim: rgba(14, 143, 208, 0.1);
  --hot: #d97a1f;
  --hot-dim: rgba(217, 122, 31, 0.12);
  --hot-glow: rgba(217, 122, 31, 0.28);
  --warn: #d97a1f;
  --warn-dim: rgba(217, 122, 31, 0.12);
  --danger: #cf4a2e;
  --danger-dim: rgba(207, 74, 46, 0.1);
  --captain: #7254c9;
  --captain-dim: rgba(114, 84, 201, 0.12);
  --idle: #8b96ad;
  --slot-premium: #cf4a2e;
  --slot-high: #d97a1f;
  --slot-medium: #0e8fd0;
  --slot-low: #8b96ad;
  --bucket-premium: var(--slot-premium);
  --bucket-high: var(--slot-high);
  --bucket-medium: var(--slot-medium);
  --bucket-low: var(--slot-low);
  --wire-accent: #0a72a8;
  --wire-hot: #e8760a;
  --wire-dim: #82b4cf; /* far side — same cyan family, lighter/desaturated */
  --wire-boost: 1.4; /* @kind other */
  --halo-boost: 1.2; /* @kind other */
  color-scheme: light;
}
/* Semantic aliases — declared on BOTH theme scopes so var() re-resolves inside [data-theme="light"] (aliases declared only on :root would freeze to dark values). */
:root,
[data-theme="light"] {
  --surface-card: var(--bg-2);
  --surface-input: var(--bg-1);
  --text-body: var(--fg-1);
  --text-muted: var(--fg-2);
  --text-faint: var(--fg-3);
  --focus-ring: 0 0 0 1px var(--line-2), 0 0 24px -6px var(--accent-glow);
}
@import "./tokens/fonts.css";
@import "./tokens/colors.css";
@import "./tokens/typography.css";
@import "./tokens/spacing.css";
@import "./tokens/effects.css";

/* The stage lifts with the composer's growth (docs/composer.md): the
   Firstmate and the card ease to their place, and land at once when the
   person has asked for less motion. */
:root {
  /* The composer's growth over one line, written by HomePrompt. */
  --prompt-rise: 0px;
  --stage-lift-duration: var(--dur-fast);
}
@media (prefers-reduced-motion: reduce) {
  :root {
    --stage-lift-duration: 0s;
  }
}

/* The window is translucent on macOS (docs/translucent-window.md): a shown
   window is the system material, the preload marks the document, and the
   body paints --material-tint over it instead of the opaque void. When the
   person has asked macOS to reduce transparency, the void comes back. */
html[data-window-material="translucent"] body {
  /* The strength is now the tint's actual opacity; default 20% shows native blur. */
  background: color-mix(in srgb, var(--material-tint) var(--wash-strength, 20%), transparent);
}
@media (prefers-reduced-transparency: reduce) {
  html[data-window-material="translucent"] body {
    background: var(--bg-0);
  }
}

/* Side rails: two dock columns framing the home stage. A rail is a flex
   column of host-framed panels at one fixed width token; an EMPTY rail is
   zero-width and paints nothing (no border, no header, no affordance), so a
   window with nothing docked is pixel-identical to one without rails. Not
   resizable. The stage insets over one motion token; it is never covered. */
/* The two docked widths are REGISTERED as lengths because the thread
   ladder reads them (`app/shellLayout.ts`). An unregistered custom property
   computes to its own token stream, so `--rail-docked-left: var(--rail-width)`
   reads back through getComputedStyle as the literal `max(300px, 20vw)` and
   parses as NaN; declared `<length>`, it resolves to an absolute px at
   computed-value time, which is what the ladder's arithmetic is in. */
@property --rail-docked-left {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}
@property --rail-docked-right {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

html {
  --rail-docked-left: 0px;
  --rail-docked-right: 0px;
  --occupied-rail-left: var(--rail-docked-left);
  --occupied-rail-right: var(--rail-docked-right);
}
html:has([data-rail="left"]:not(:empty)) {
  --rail-docked-left: var(--rail-width);
}
html:has([data-rail="right"]:not(:empty)) {
  --rail-docked-right: var(--rail-width);
}

/* The fold (cards-as-threads phase 1, the captain's tweak 2): while a
   card's thread is open beside it and the pair would leave the card under
   400px, the docked rails give their width back and the stage becomes the
   whole window. This is not collapse - a collapsed dock still holds its
   full --rail-width, which is why collapsing frees nothing. The rails keep
   their panels, so --rail-docked-* still says what they ask for and the
   ladder that folded them can un-fold them; only the effective width goes.
   The panels return when the thread closes. */
html[data-rails-folded] {
  --occupied-rail-left: 0px;
  --occupied-rail-right: 0px;
}
html[data-rails-folded] [data-rail]:not(:empty) {
  width: 0;
  padding: 0;
}
[data-rail] {
  flex: 0 0 auto;
  box-sizing: border-box;
  width: var(--rail-width);
  pointer-events: auto;
  min-width: 0;
  padding: var(--space-8) var(--space-3) max(var(--space-4), env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  overflow: hidden;
  resize: none;
  transition:
    width var(--dur-med) var(--ease-out),
    padding var(--dur-med) var(--ease-out);
}
[data-rail]:empty {
  width: 0;
  padding: 0;
}
[data-side-panel] {
  flex: 0 1 auto;
  min-height: 0;
  width: calc(var(--rail-width) - var(--space-3) * 2);
}
[data-side-panel-placement-y="bottom"] {
  margin-top: auto;
}

/* A `fill` panel takes the rail height its siblings leave; collapsed, it
   hugs its header like any other. Its body is a flex column so a frame
   inside can take the whole of it. */
[data-side-panel][data-side-panel-size="fill"]:not([data-side-panel-collapsed]) {
