import type React from "react";
import { Badge, type BadgeTone } from "../core/Badge";
import { IconButton } from "../core/IconButton";
import { ModelChip } from "../core/ModelChip";

/**
 * The chrome a card wears, derived from what it is and never declared on
 * the wire (cards/tasks/agents P1, ruling D1 a): `decision` has actions,
 * `note` has none, `attention` is the host's own (the agent-down set);
 * `working` is a card mid-revision and `record` a task's record.
 */
export type ResponseCardKind = "decision" | "note" | "attention" | "working" | "record";

export type ResponseCardProps = {
  kind?: ResponseCardKind;
  title?: string;
  /** Mono metadata line: relative time, crewmate ref. */
  meta?: string;
  /**
   * The model its author ran on: an outline mono chip right after the meta
   * line, which gives way to it (the chip is never truncated or pushed out).
   */
  model?: string;
  /** Action button row (app-owned chrome), right-aligned. */
  actions?: React.ReactNode;
  /** Top-right chrome close; not a declared card action. */
  onClose?: () => void;
  children?: React.ReactNode;
  width?: number | string;
  minHeight?: number;
  /**
   * Whether the card draws its own surface. False when it is one COLUMN of
   * a larger container - a card with its thread open beside it, which is one
   * acrylic surface, one border, one radius and one shadow for the pair
   * (design skill `components/cards/CardThread.prompt.md`). The card's own
   * height cap goes with it: the container caps the pair.
   */
  surface?: boolean;
  /** Extra chrome in the head, between the badge and the meta line. */
  headExtra?: React.ReactNode;
  /**
   * Host chrome below the action row - the card's reply row while it has no
   * thread yet (design skill `components/cards/CardThread.prompt.md`). It is
   * never a card action and never wraps into that row.
   */
  footer?: React.ReactNode;
  style?: React.CSSProperties;
};

const closeIcon = (
  <svg
    width="16"
    height="16"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth={1.5}
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
  >
    <path d="M18 6 6 18M6 6l12 12" />
  </svg>
);

const cardKinds: Record<ResponseCardKind, { label: string; tone: BadgeTone }> = {
  decision: { label: "Decision", tone: "accent" },
  note: { label: "Note", tone: "neutral" },
  attention: { label: "Attention", tone: "danger" },
  working: { label: "Working", tone: "accent" },
  /** A task's record (task-system P4): never any card actions; its footer is the host's. */
  record: { label: "Task", tone: "neutral" },
};

/**
 * The tallest a card on the stage may be. The stack is centred 60px above
 * the stage's middle and carries a pager under the card; at the shortest
 * window (640px) this keeps the card's top clear of the 52px top bar, so
 * close is never under the drag region. The composer's growth
 * (`--prompt-rise`) comes off it, so the air between a tall card and a
 * multi-line input never closes (docs/composer.md). A taller body scrolls
 * inside the card.
 */
export const CARD_MAX_HEIGHT = "calc(100vh - 3 * var(--space-9) - var(--prompt-rise))";

export function ResponseCard({
  kind = "note",
  title,
  meta,
  model,
  actions,
  onClose,
  children,
  width = 560,
  minHeight = 340,
  surface = true,
  headExtra,
  footer,
  style,
}: ResponseCardProps) {
  const k = cardKinds[kind] || cardKinds.note;
  return (
    <div
      style={{
        width,
        // The floor gives way to the cap (CARD_MAX_HEIGHT) when a tall
        // composer shrinks it, here and as one column of the pair.
        minHeight: `min(${minHeight}px, ${CARD_MAX_HEIGHT})`,
        ...(surface
          ? {
              maxHeight: CARD_MAX_HEIGHT,
              background: "var(--acrylic-bg)",
              backdropFilter: "var(--acrylic-blur)",
              WebkitBackdropFilter: "var(--acrylic-blur)",
              border: "1px solid var(--acrylic-border)",
              borderRadius: "var(--radius-l)",
              boxShadow: "var(--acrylic-shadow)",
            }
          : { minWidth: 0 }),
        boxSizing: "border-box",
        display: "flex",
        flexDirection: "column",
        overflow: "hidden",
        ...style,
      }}
    >
      <div
        data-card-head=""
        style={{ display: "flex", alignItems: "center", gap: 10, padding: "14px 12px 0 20px" }}
      >
        <Badge tone={k.tone} dot style={{ flexShrink: 0 }}>
          {k.label}
        </Badge>
        {headExtra}
        {(meta || model) && (
          // The meta line and the model chip share the room between the
          // chip and close. A long meta line (crewmate ref carrying a repo
          // name) truncates with an ellipsis instead of wrapping the card
          // header, and it is the one that gives way: the chip keeps its
          // whole name, wrapping inside itself only when the name is longer
          // than all the room there is.
          <span
            style={{
              display: "flex",
              alignItems: "center",
              gap: 10,
              minWidth: 0,
              flex: 1,
            }}
          >
            {meta && (
              <span
                data-card-meta=""
                style={{
                  fontFamily: "var(--font-mono)",
                  fontSize: "var(--text-xs)",
                  color: "var(--fg-3)",
                  whiteSpace: "nowrap",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                  minWidth: 0,
                  flex: model ? "0 1 auto" : 1,
                }}
              >
                {meta}
              </span>
            )}
            {model && <ModelChip label={model} />}
          </span>
        )}
        <IconButton label="Close" onClick={onClose} style={{ marginLeft: "auto", flexShrink: 0 }}>
          {closeIcon}
        </IconButton>
      </div>
      {title && (
        <div
          style={{
            padding: "10px 20px 0",
            fontSize: "var(--text-lg)",
            fontWeight: 500,
            letterSpacing: "var(--tracking-display)",
            color: "var(--fg-1)",
            lineHeight: "var(--leading-tight)",
          }}
        >
          {title}
        </div>
      )}
      <div
        data-card-body=""
        style={{
          flex: 1,
          minHeight: 0,
          // Keep the frame's width independent of overflow: a scrollbar that
          // takes width shrinks fluid content, whose height report can remove
          // that same scrollbar and start an endless resize feedback loop.
          overflowY: "auto",
          scrollbarGutter: "stable",
          padding: "12px 20px 18px",
          fontSize: "var(--text-base)",
          color: "var(--fg-2)",
          lineHeight: "var(--leading-body)",
        }}
      >
        {children}
      </div>
      {actions && (
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            justifyContent: "flex-end",
            gap: "var(--space-2)",
            rowGap: "var(--space-2)",
            // Keep the body separate from its choices and keep air above the
            // footer's hairline.
            padding: footer ? "var(--space-3) 16px var(--space-3)" : "var(--space-3) 16px 16px",
          }}
        >
          {actions}
        </div>
      )}
      {footer && <div style={{ padding: "0 16px 16px", flexShrink: 0 }}>{footer}</div>}
    </div>
  );
}
import type React from "react";
import { Badge } from "../core/Badge";
import { IconButton } from "../core/IconButton";

const csIcoS = {
  fill: "none",
  stroke: "currentColor",
  strokeWidth: 1.5,
  strokeLinecap: "round",
  strokeLinejoin: "round",
} as const;

/** The stack's design width; the stage narrows it on a narrow window. */
export const CARD_STACK_WIDTH = 560;

/** The unread dot on an arrow that leads to an unseen card (design skill CardStack). */
const unreadDot: React.CSSProperties = {
  position: "absolute",
  top: 6,
  right: 6,
  width: 6,
  height: 6,
  borderRadius: "var(--radius-pill)",
  background: "var(--accent)",
  boxShadow: "0 0 0 2px var(--bg-0)",
  pointerEvents: "none",
};

export type CardStackProps = {
  index?: number;
  count?: number;
  /** Unseen cards before the shown one: a dot on "Previous card". */
  unreadBefore?: number;
  /** Unseen cards after the shown one: a dot on "Next card". */
  unreadAfter?: number;
  onPrev?: () => void;
  onNext?: () => void;
  width?: number | string;
  children?: React.ReactNode;
  peekStyle?: React.CSSProperties;
  style?: React.CSSProperties;
};

export function CardStack({
  index = 0,
  count = 1,
  unreadBefore = 0,
  unreadAfter = 0,
  onPrev,
  onNext,
  width = CARD_STACK_WIDTH,
  children,
  peekStyle,
  style,
}: CardStackProps) {
  const peekBase: React.CSSProperties = {
    position: "absolute",
    background: "var(--acrylic-bg)",
    backdropFilter: "var(--acrylic-blur)",
    WebkitBackdropFilter: "var(--acrylic-blur)",
    border: "1px solid var(--acrylic-border)",
    borderBottom: "none",
    borderRadius: "var(--radius-l) var(--radius-l) 0 0",
    height: 14,
  };
  const unread = unreadBefore + unreadAfter;
  return (
    <div style={{ position: "relative", width, ...style }}>
      {count > 2 && (
        <div style={{ ...peekBase, left: 14, right: 14, top: -14, ...peekStyle, opacity: 0.35 }} />
      )}
      {count > 1 && (
        <div style={{ ...peekBase, left: 7, right: 7, top: -7, ...peekStyle, opacity: 0.65 }} />
      )}
      <div style={{ position: "relative" }}>{children}</div>
      {count > 1 && (
        <div style={{ display: "flex", justifyContent: "center", marginTop: 10 }}>
          <div style={{ position: "relative", display: "flex", alignItems: "center", gap: 6 }}>
            <span style={{ position: "relative", display: "inline-flex" }}>
              <IconButton label="Previous card" size={28} onClick={onPrev} disabled={index <= 0}>
                <svg width="14" height="14" viewBox="0 0 24 24" {...csIcoS} aria-hidden="true">
                  <path d="m15 18-6-6 6-6" />
                </svg>
              </IconButton>
              {unreadBefore > 0 && <span data-unread-dot="before" style={unreadDot} />}
            </span>
            <span
              style={{
                fontFamily: "var(--font-mono)",
                fontSize: "var(--text-xs)",
                color: "var(--fg-3)",
              }}
            >
              {index + 1} / {count}
            </span>
            <span style={{ position: "relative", display: "inline-flex" }}>
              <IconButton
                label="Next card"
                size={28}
                onClick={onNext}
                disabled={index >= count - 1}
              >
                <svg width="14" height="14" viewBox="0 0 24 24" {...csIcoS} aria-hidden="true">
                  <path d="m9 18 6-6-6-6" />
                </svg>
              </IconButton>
              {unreadAfter > 0 && <span data-unread-dot="after" style={unreadDot} />}
            </span>
            {unread > 0 && (
              // Outside the centred arrow group's flow, so the arrows never
              // move under the pointer as the badge comes and goes.
              <span
                role="status"
                style={{
                  position: "absolute",
                  left: "100%",
                  marginLeft: "var(--space-2)",
                  whiteSpace: "nowrap",
                }}
              >
                <Badge tone="accent" mono>
                  {unread} new
                </Badge>
              </span>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
/* Firstmate 3000 — radii, shadows, glow, blur, motion. */
:root {
