   hugs its header like any other. Its body is a flex column so a frame
   inside can take the whole of it. */
[data-side-panel][data-side-panel-size="fill"]:not([data-side-panel-collapsed]) {
  flex: 1 1 auto;
}
[data-side-panel][data-side-panel-size="fill"] > [data-side-panel-body] {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* Placeholder text stays centered in the empty voice input, but the field
   itself is left-aligned so the caret blinks on the left, not the center. */
[data-voice-input-field]::placeholder {
  text-align: center;
}

