  applyThread: (cardId, messages) =>
    // The thread paints at once; whether its card is on the stage is the
    // core's `awaiting`, which the cards push carries.
    set((s) => ({
      threads: { ...s.threads, [cardId]: messages },
      // A message arriving on a thread the captain closed re-opens it: the
      // author answered, and an answer he cannot see is worse than a column.
      closedThreadIds:
        messages.length > 0 ? s.closedThreadIds.filter((id) => id !== cardId) : s.closedThreadIds,
    })),
  setReplyDraft: (cardId, text) =>
    set((s) => ({
      replyDrafts: { ...s.replyDrafts, [cardId]: text },
      replyErrors: withoutKey(s.replyErrors, cardId),
    })),
  attachReplyImages: (cardId, items) =>
    set((s) => {
      const held = s.replyImages[cardId] ?? [];
      const { taken, refused } = takePictures(held, items);
      return {
        replyImages: { ...s.replyImages, [cardId]: [...held, ...taken] },
        replyErrors: withoutKey(s.replyErrors, cardId),
