  sendReply: async (cardId) => {
    const text = composeTurnText(get().replyDrafts[cardId] ?? "", []);
    const images = get().replyImages[cardId] ?? [];
    if ((!text && images.length === 0) || get().sendingReplies[cardId]) return;
    // The offer the reply was typed under, as the stage shows it now.
    const submission = submissionFor(get().cards.find((card) => card.id === cardId));
    // Past a reply's limit nothing leaves and the draft stays; the row
    // already says so under the field.
    if (text.length > CARD_REPLY_MAX_CHARS) return;
    set((s) => ({
      sendingReplies: { ...s.sendingReplies, [cardId]: true },
      replyErrors: withoutKey(s.replyErrors, cardId),
    }));
    // Sending hands the turn to the author: the card leaves the stage now,
    // as the core's own push will say it did (`awaiting: "answer"`), and
    // comes back when that push says its author closed out.
    get().applyCards(
      get().cards.map((card) =>
        card.id === cardId ? { ...card, awaiting: "answer" as const } : card,
      ),
    );
    try {
      const payload =
        images.length > 0
          ? {
              text: text || undefined,
              images: images.map((image) => ({ mimeType: image.mimeType, data: image.data })),
            }
          : text;
      const thread = await window.firstmate.cards.reply(cardId, payload, submission);
      get().applyThread(thread.cardId, thread.messages);
      set((s) => ({
        replyDrafts: withoutKey(s.replyDrafts, cardId),
        replyImages: withoutKey(s.replyImages, cardId),
        replyNotices: withoutKey(s.replyNotices, cardId),
      }));
    } catch (caught) {
      const message = caught instanceof Error ? caught.message : String(caught);
      // The draft stays: a refused reply is never words the captain retypes,
      // and the card it was typed under is back where it was.
      set((s) => ({
        replyErrors: { ...s.replyErrors, [cardId]: message },
        sendingReplies: withoutKey(s.sendingReplies, cardId),
      }));
      get().applyCards(
        get().cards.map((card) => {
          if (card.id !== cardId || card.awaiting !== "answer") return card;
          const { awaiting: _answer, ...shown } = card;
          return shown;
        }),
      );
    } finally {
      set((s) => ({ sendingReplies: withoutKey(s.sendingReplies, cardId) }));
      const stackAtRead = get().cards;
      void window.firstmate.cards
        .list?.()
        .then((cards) => {
          if (get().cards === stackAtRead) get().applyCards(cards);
        })
        .catch(() => {});
    }
  },
  closeThread: (cardId) =>
    set((s) =>
      s.closedThreadIds.includes(cardId) ? {} : { closedThreadIds: [...s.closedThreadIds, cardId] },
    ),
  openThread: (cardId) =>
    set((s) => ({ closedThreadIds: s.closedThreadIds.filter((id) => id !== cardId) })),
  openRecord: (taskId, anchor = null) => {
    // The pane does not touch the stack: no index moves, nothing is marked
    // seen, and whatever card was up stays up beside it.
    set({ record: { taskId, anchor } });
  },
  pointRecord: (taskId, anchor) => {
    // The frame re-reports its row as the panel scrolls or resizes. A report
    // for a task that is no longer the open one is stale and dropped.
    set((s) => {
      if (s.record?.taskId !== taskId) return {};
      const held = s.record.anchor;
      if (held?.top === anchor?.top && held?.height === anchor?.height) return {};
      return { record: { taskId, anchor } };
    });
  },
  closeRecord: () => {
    set((s) => {
      if (!s.record) return {};
      // The prompt takes focus back, the way it does when a card is lost.
      return { record: null, focusRequest: s.focusRequest + 1 };
    });
  },
  focusCard: (cardId) => {
    // Pointing at a collapsed note brings it back onto the stack.
    const collapsedCardIds = get().collapsedCardIds.filter((id) => id !== cardId);
    const index = visibleCards(get().cards, collapsedCardIds).findIndex(
      (card) => card.id === cardId,
    );
    if (index < 0) return false;
    set((s) => ({
      cardIndex: index,
      collapsedCardIds,
      unreadCardIds: s.unreadCardIds.filter((id) => id !== cardId),
      phase: derivePhase(s.recording, s.cards, s.firstmateBusy, collapsedCardIds),
    }));
    return true;
  },
  applyCards: (incoming) => {
    const cards = incoming.map((card) =>
      get().sendingReplies[card.id] ? { ...card, awaiting: "answer" as const } : card,
    );
    let noticed = 0;
    set((s) => {
      const reconciled = reconcileStack(s, cards, Date.now());
      noticed = reconciled.noticed;
      const present = new Set(cards.map((card) => card.id));
      return {
        cards,
        ...reconciled.state,
        pendingCardActions: Object.fromEntries(
          Object.entries(s.pendingCardActions).filter(([id]) => present.has(id)),
        ),
        cardActionErrors: Object.fromEntries(
          Object.entries(s.cardActionErrors).filter(([id]) => present.has(id)),
        ),
        cardAnswers: Object.fromEntries(
          Object.entries(s.cardAnswers).filter(([id]) => present.has(id)),
        ),
        cardDrags: Object.fromEntries(
          Object.entries(s.cardDrags).filter(([id]) => present.has(id)),
        ),
        phase: derivePhase(s.recording, cards, s.firstmateBusy, reconciled.state.collapsedCardIds),
        focusRequest: reconciled.lostCard ? s.focusRequest + 1 : s.focusRequest,
      };
    });
    // A card landed behind the shown one: the character's notice pulse, a
    // side channel like the emotes - never shell state.
    if (noticed > 0) requestCharacterNotice();
