import {
  type Card,
  type CardActionSource,
  type CardWidth,
  cardPresentation,
  cardTakesReplies,
} from "@shared/cards";
import {
  FIRST_RUN_PLACEHOLDER,
  FIRST_RUN_PLACEHOLDER_NO_VOICE,
  type FirstRunView,
  GATED_PLACEHOLDER,
  isFirstRunHint,
  STANDARD_PLACEHOLDER,
  STANDARD_PLACEHOLDER_NO_VOICE,
} from "@shared/firstRun";
import type { FrameAnswers, FramePicture } from "@shared/plugins/bridge";
import { memo, useEffect, useRef, useState } from "react";
import { bridgeActionIds } from "../cards/bridgeActions";
import { CardThread, MessageList, ReplyRow, ThreadSegments } from "../cards/CardThread";
import {
  CARD_DRAG_MIN,
  CARD_SIZES,
  cardEdgesEase,
  cardPlacement,
  cardShift,
