        data-card-size={shownCardSize(shownWidth)}
        style={{
          position: "fixed",
          left: "50%",
          // Lifted by half the composer's growth (docs/composer.md).
          top: STAGE_TOP,
          transform: "translate(-50%,-50%)",
          marginLeft: shift,
          width: layerWidth,
          // The pair is sized to fit the stage by construction; a lone card
          // is held under the stage's own edge as well.
          ...(beside ? {} : { maxWidth: STAGE_CEILING }),
          // Paging between widths, the host's re-decision on a revision and
          // the fold all move the edges over one duration; the captain's
          // own drag follows his pointer, and a resized window or dock is
          // followed at once.
          transition: eases
            ? `width var(--dur-med) var(--ease-out), margin-left var(--dur-med) var(--ease-out), ${STAGE_LIFT_EASE}`
            : STAGE_LIFT_EASE,
        }}
      >
        <CardStack
          index={index}
          count={shown.length}
          unreadBefore={unread.before}
          unreadAfter={unread.after}
          width="100%"
          onPrev={prevCard}
          onNext={nextCard}
        >
          {beside ? (
            // ONE container for the pair (the captain's tweak 1): one
            // surface, one border, one radius, one shadow, and a single
            // hairline between the columns - the thread column's own left
            // border. No gap, and no second shadow.
            <div
              data-card-pair=""
              style={{
                display: "flex",
                alignItems: "stretch",
                maxHeight: CARD_MAX_HEIGHT,
                boxSizing: "border-box",
                background: "var(--acrylic-bg)",
                backdropFilter: "var(--acrylic-blur)",
                WebkitBackdropFilter: "var(--acrylic-blur)",
                border: "1px solid var(--acrylic-border)",
                borderRadius: "var(--radius-l)",
                boxShadow: "var(--acrylic-shadow)",
                overflow: "hidden",
              }}
            >
              <StackedCard
                key={card.id}
                card={card}
                chrome={kind.chrome}
                bodyPolicy={kind.body}
                theme={theme}
                surface={false}
                width={beside.card}
                size={shownCardSize(beside.card)}
                onClose={requestClose}
                closeConfirm={closeConfirm}
                onAction={onCardAction}
                onPicture={openPictures}
              />
              <CardThread
                cardId={cardId}
                author={card.meta || "the card's author"}
                model={card.model}
                working={
                  card.author === "firstmate"
                    ? firstmateBusy
                    : card.author === "crewmate" &&
                      card.taskId !== undefined &&
                      crewStatusOf(crewActivity[card.taskId] ?? null) === "working"
                }
                width={beside.thread}
                onClose={requestClose}
              />
            </div>
          ) : (
            <StackedCard
              key={card.id}
              card={card}
              chrome={kind.chrome}
              bodyPolicy={kind.body}
              theme={theme}
              width="100%"
              size={shownCardSize(shownWidth)}
              onClose={requestClose}
              closeConfirm={closeConfirm}
              onAction={onCardAction}
              onPicture={openPictures}
              // The last rung: the card's body becomes the thread behind a
              // segmented control. It needs a stage under 720px, which the
              // app's own 960px window minimum puts out of reach.
              inPlaceThread={placement?.home === "in-place"}
              threadWorking={
                card.author === "firstmate"
                  ? firstmateBusy
                  : card.author === "crewmate" &&
                    card.taskId !== undefined &&
                    crewStatusOf(crewActivity[card.taskId] ?? null) === "working"
              }
              // Tweak 3: with no thread yet, the reply row is the very bottom
              // of the card, below the action row and one hairline under it.
              reply={replyable && !threadOpen}
            />
          )}
          {lone && (
            <CardEdges
              width={shownWidth}
              max={dragMax}
              onDragging={setDragging}
              onDrag={(width) => dragCard(cardId, width)}
              onReset={() => dragCard(cardId, null)}
            />
          )}
        </CardStack>
      </div>
      {viewing && (
        <PictureViewer
          title={viewing.title}
          pictures={viewing.pictures}
          index={viewing.index}
          onClose={() => {
            setViewer(null);
            viewing.opener?.focus();
          }}
        />
      )}
    </>
  );
}

/** An open picture viewer: the card it came from, its set, and the frame to return focus to. */
