/** How far one arrow key moves a card's edge. */
const EDGE_KEY_STEP = 16;

/**
 * The captain's drag on a lone card's edges (his Q5 A: facts, then the
 * author's hint, then his own hand). The card is centred, so one edge moved
 * by a pixel moves the other the same way and the card grows by two. It
 * holds while the card is up and through its revisions; a double click
 * gives the card back the width the host decided. Never a setting.
 */
function CardEdges({
  width,
  max,
  onDragging,
  onDrag,
  onReset,
}: {
  /** The card's shown width, in px. */
  width: number;
  max: number;
  onDragging: (dragging: boolean) => void;
  onDrag: (width: number) => void;
  onReset: () => void;
}) {
  const held = useRef<{ pointer: number; x: number; width: number; grow: 1 | -1 } | null>(null);
  const [lit, setLit] = useState<"left" | "right" | null>(null);
  const clamp = (next: number) => Math.round(Math.min(max, Math.max(CARD_DRAG_MIN, next)));
  const edge = (side: "left" | "right") => {
    // Moving the right edge right widens the card; the left edge, left.
    const grow = side === "right" ? 1 : -1;
    const active = lit === side;
    return (
      // biome-ignore lint/a11y/useSemanticElements: a focusable window splitter (WAI-ARIA separator with a value), which an <hr> cannot be
      <div
        key={side}
        role="separator"
        aria-orientation="vertical"
        aria-label="Resize card"
        aria-valuemin={CARD_DRAG_MIN}
        aria-valuemax={max}
        aria-valuenow={Math.round(width)}
        tabIndex={0}
        data-card-edge={side}
        onPointerEnter={() => setLit(side)}
        onPointerLeave={() => {
          if (!held.current) setLit(null);
        }}
        onFocus={() => setLit(side)}
        onBlur={() => setLit(null)}
        onPointerDown={(event) => {
          if (event.button !== 0) return;
          event.preventDefault();
          event.currentTarget.setPointerCapture(event.pointerId);
          held.current = { pointer: event.pointerId, x: event.clientX, width, grow };
          onDragging(true);
        }}
        onPointerMove={(event) => {
          const start = held.current;
          if (!start || start.pointer !== event.pointerId) return;
          onDrag(clamp(start.width + 2 * start.grow * (event.clientX - start.x)));
        }}
        onPointerUp={(event) => {
          if (held.current?.pointer !== event.pointerId) return;
          held.current = null;
          onDragging(false);
          setLit(null);
        }}
        onPointerCancel={() => {
          held.current = null;
          onDragging(false);
          setLit(null);
        }}
        onDoubleClick={onReset}
        onKeyDown={(event) => {
          const step =
            event.key === "ArrowRight"
              ? grow * EDGE_KEY_STEP
              : event.key === "ArrowLeft"
                ? -grow * EDGE_KEY_STEP
                : 0;
          if (step !== 0) onDrag(clamp(width + 2 * step));
          else if (event.key === "Home") onDrag(CARD_DRAG_MIN);
          else if (event.key === "End") onDrag(clamp(max));
          else return;
          event.preventDefault();
        }}
        style={{
          position: "absolute",
          top: "var(--space-4)",
          bottom: "var(--space-4)",
          [side]: -6,
          width: 12,
          cursor: "ew-resize",
          outline: "none",
          touchAction: "none",
          zIndex: 1,
        }}
      >
        {/* The grip shows only while the edge is under the pointer, held or focused. */}
        <span
          aria-hidden="true"
          style={{
            position: "absolute",
            left: 4,
            top: "50%",
            width: 4,
            height: 32,
            marginTop: -16,
            borderRadius: "var(--radius-pill)",
            background: "var(--accent)",
            opacity: active ? 1 : 0,
            transition: "opacity var(--dur-fast) var(--ease-out)",
          }}
        />
      </div>
    );
  };
  return (
    <>
      {edge("left")}
      {edge("right")}
    </>
  );
}

/**
 * A card footer's two groups, in order: the quiet actions (ghost: explain
 * more) and the choices ending in the default. An empty group is dropped.
 */
function footerGroups(actions: Card["actions"]) {
  const quiet = actions.filter((action) => action.variant === "ghost");
  const choices = actions.filter((action) => action.variant !== "ghost");
  return [
    { key: "quiet", actions: quiet },
    { key: "choices", actions: choices },
  ].filter((group) => group.actions.length > 0);
}

/** The lifecycle and offer of a mounted card, as a gesture on it reports them. */
function mountOf(card: Card): CardMount {
  return {
    ...(card.lifecycleId ? { lifecycleId: card.lifecycleId } : {}),
    ...(card.offerId ? { offerId: card.offerId } : {}),
  };
}

/**
 * The footer's queue group (inline decisions, contract 4.22): how many of
 * the questions the body asks have an answer, and how many of those answers
 * differ from what the card proposed. Picks wait here until a footer button
 * sends them; nothing in the body sends on its own.
 */
function answersLine(answers: FrameAnswers): string {
  const count = `${answers.answered} of ${answers.of} answered`;
  return answers.changed > 0 ? `${count} · ${answers.changed} changed` : count;
}

type StackedCardProps = {
  card: Card;
  chrome: CardKindContribution["chrome"];
  bodyPolicy: CardKindContribution["body"];
  theme: Theme;
  width?: number | string;
  /** The size the card is shown at, told to its body's document. */
  size: CardWidth;
  /** False when the card is one column of the pair's single container. */
  surface?: boolean;
  /** Show the reply row at the foot of the card (no thread open beside it). */
  reply?: boolean;
  /** The in-place rung: the body becomes the thread behind a segmented control. */
  inPlaceThread?: boolean;
  threadWorking?: boolean;
  onClose: () => void;
  /** The close is asking first: changed picks would go unsent (Q3 A). */
  closeConfirm?: { onClose: () => void; onKeep: () => void } | undefined;
  onAction: (
    actionId: string,
    source?: CardActionSource,
    value?: unknown,
    collect?: CollectAnswers,
    mounted?: CardMount,
  ) => void;
  onPicture?: React.ComponentProps<typeof HtmlCardBody>["onPicture"];
};

/** A persisted card in its derived chrome, body in the sandboxed frame. */
function StackedCard({
  card,
  chrome,
  bodyPolicy,
  theme,
  width = "100%",
  size,
  surface = true,
  reply = false,
  inPlaceThread = false,
  threadWorking = false,
  onClose,
  closeConfirm,
  onAction,
  onPicture,
}: StackedCardProps) {
  const pending = useShellStore((s) => s.pendingCardActions[card.id]);
  const error = useShellStore((s) => s.cardActionErrors[card.id]);
  const messages = useShellStore((s) => s.threads[card.id]) ?? [];
  const answers = useShellStore((s) => s.cardAnswers[card.id]);
  const setCardAnswers = useShellStore((s) => s.setCardAnswers);
  const collectRef = useRef<CollectAnswers | null>(null);
  const [showing, setShowing] = useState<"card" | "thread">("card");
  const streaming = card.status === "streaming";
  const showThread = inPlaceThread && showing === "thread";
  const asking = answers !== undefined && answers.of > 0;
  // A closing choice waits until every question the body requires has an
  // answer (the captain's Q2 A); a non-closing one sends what there is.
  const unanswered = asking && answers.answered < answers.of;
  const collect: CollectAnswers = () =>
    collectRef.current?.() ?? Promise.resolve(useShellStore.getState().cardAnswers[card.id]);
  const footer = closeConfirm ? (
    <CloseConfirm changed={answers?.changed ?? 0} {...closeConfirm} />
  ) : card.actions.length > 0 ? (
    <>
      {asking && (
        <span
          data-card-answers=""
          aria-live="polite"
          style={{
            alignSelf: "center",
            marginRight: "auto",
            fontFamily: "var(--font-mono)",
            fontSize: "var(--text-xs)",
            color: "var(--fg-3)",
            whiteSpace: "nowrap",
          }}
        >
          {answersLine(answers)}
        </span>
      )}
      {footerGroups(card.actions).map((group) => (
        // Each group stays on one row: a narrow card moves the choices
        // down together, never the default alone (design skill
        // ResponseCard footer rule).
        <div
          key={group.key}
          style={{
            display: "flex",
            gap: "var(--space-2)",
            flexWrap: "nowrap",
            minWidth: 0,
            maxWidth: "100%",
          }}
        >
          {group.actions.map((action) => (
            <Button
              key={action.id}
              variant={action.variant ?? "secondary"}
              style={{
                minWidth: 0,
                maxWidth: "100%",
                flexShrink: 1,
                whiteSpace: "normal",
                overflowWrap: "anywhere",
              }}
              pending={pending?.actionId === action.id}
              // A card revising after "explain more" (WI-10) waits for
              // its new body before any choice.
              disabled={Boolean(pending) || streaming || (unanswered && !action.keepsOpen)}
              // The offer this footer belongs to rides the click, read now.
              onClick={() => onAction(action.id, "chrome", undefined, collect, mountOf(card))}
            >
              {action.label}
            </Button>
          ))}
        </div>
      ))}
    </>
  ) : undefined;
  return (
    <ResponseCard
      kind={streaming ? "working" : chrome}
      title={card.title}
      meta={card.meta}
      model={card.model}
      width={width}
      surface={surface}
      headExtra={
        inPlaceThread ? (
          <ThreadSegments showing={showing} count={messages.length} onShow={setShowing} />
        ) : undefined
      }
      footer={reply || inPlaceThread ? <ReplyRow cardId={card.id} /> : undefined}
      onClose={onClose}
      actions={footer}
    >
      {error && (
        <p role="alert" style={{ color: "var(--danger)", fontSize: "var(--text-sm)" }}>
          {error}
        </p>
      )}
      {showThread ? (
        <MessageList messages={messages} working={threadWorking} />
      ) : streaming && bodyPolicy.streaming === "plain" ? (
        <LinkedText text={card.body} />
      ) : (
        <HtmlCardBody
          body={card.body}
          theme={theme}
          title={card.title}
          // An effect-bearing action is the host chrome's own button and is
          // never declared to the body's frame (`bridgeActionIds`): a card
          // script must not be able to merge its own PR at mount.
          declaredActionIds={bridgeActionIds(card.actions)}
          width={size}
          onAction={(actionId, value) =>
            onAction(actionId, "frame", value, undefined, mountOf(card))
          }
          onPicture={onPicture}
          form={{
            fill: () => useShellStore.getState().cardAnswers[card.id]?.answers,
            onAnswers: (reading) => setCardAnswers(card.id, reading),
          }}
          collectRef={collectRef}
        />
      )}
    </ResponseCard>
  );
}

/**
 * The close's one question (the captain's Q3 A), in the card's own footer:
 * closing sends nothing, so the captain's changed picks would be lost.
 */
function CloseConfirm({
  changed,
  onClose,
  onKeep,
}: {
  changed: number;
  onClose: () => void;
  onKeep: () => void;
}) {
  return (
    <fieldset
      aria-label="Close this card?"
      data-card-close-confirm=""
      style={{
        margin: 0,
        padding: 0,
        border: "none",
        minWidth: 0,
        display: "flex",
        flexWrap: "wrap",
        alignItems: "center",
        justifyContent: "flex-end",
        gap: "var(--space-2)",
        width: "100%",
      }}
    >
      <span style={{ marginRight: "auto", fontSize: "var(--text-sm)", color: "var(--fg-2)" }}>
        {changed === 1
          ? "You changed 1 answer. Closing does not send it."
          : `You changed ${changed} answers. Closing does not send them.`}
      </span>
      <div style={{ display: "flex", gap: "var(--space-2)", flexWrap: "nowrap" }}>
        <Button variant="secondary" onClick={onKeep}>
          Keep answering
        </Button>
        <Button onClick={onClose}>Close</Button>
      </div>
    </fieldset>
  );
}

