import type { CardWidth } from "@shared/cards";
import { cardWidth, THREAD_CARD_MAX, THREAD_STAGE_MARGIN } from "./threadGeometry";

/**
 * How wide a card is on the stage (the captain's Q5 to Q7 A of 2026-09-28,
 * proposal 2 of `fm3000-card-decisions-width-s1`). The arithmetic lives
 * here, away from the DOM, for the reason `threadGeometry.ts` does: it is
 * the whole of the behaviour worth pinning, and `threadGeometry.test.ts`
 * walks it at the window sizes the captain reviewed.
 *
 * Who decides, in order: the host at emit (`Card.width`, from the body's
 * facts and the author's hint), then the captain's drag on either edge,
 * which holds while the card is up and through its revisions and is never
 * a setting. Every width is clamped to the stage less its margin, as 560
 * always was.
 */

/** Each size's design width; `full` is the stage itself, up to this. */
export const CARD_SIZES: Record<CardWidth, number> = { regular: 560, wide: 800, full: 1_040 };
/** The narrowest the captain's drag takes a card. */
export const CARD_DRAG_MIN = 480;
/**
 * A card wider than regular needs this much of the docked stage; under it,
 * with a dock occupied, the docks fold as they do for a thread and unfold
 * when the card leaves.
 */
export const WIDE_CARD_ROOM = 720;

/** What the width rules read off a card: the host's size and the captain's drag. */
export type SizedCard = {
  width?: "wide" | "full" | undefined;
  /** The captain's drag, in px, while the card is up. */
  dragged?: number | undefined;
};

/** What a card asks for, in px, before any stage: the captain's drag, else its size. */
export function requestedCardWidth(card: SizedCard): number {
  if (card.dragged !== undefined) {
    return Math.round(Math.min(CARD_SIZES.full, Math.max(CARD_DRAG_MIN, card.dragged)));
  }
  return CARD_SIZES[card.width ?? "regular"];
}

/** The card's width on a stage with no thread beside it. */
export function cardWidthFor(card: SizedCard, stage: number): number {
  return cardWidth(stage, requestedCardWidth(card));
}

/** Where a lone card goes: its width, and whether the docks folded to give it. */
export type CardPlacement = { folded: boolean; card: number };

/**
 * A card with no thread open, for a window of `windowWidth` with
 * `railsWidth` of docked rails. A regular card never folds anything. A
 * wider one folds the docks when the docked stage cannot give it
 * `WIDE_CARD_ROOM` (or all it asks, when it asks for less), and takes the
 * whole window instead - the same fold the thread's second rung uses.
 */
export function cardPlacement(
  windowWidth: number,
  railsWidth: number,
  card: SizedCard,
): CardPlacement {
  const requested = requestedCardWidth(card);
  const stage = windowWidth - railsWidth;
  const room = stage - THREAD_STAGE_MARGIN;
  if (requested > THREAD_CARD_MAX && railsWidth > 0 && room < Math.min(requested, WIDE_CARD_ROOM)) {
    return { folded: true, card: cardWidth(windowWidth, requested) };
  }
  return { folded: false, card: cardWidth(stage, requested) };
}

/**
 * How far a lone card moves off the window's centre to stay on the stage.
 * A lone card is a window overlay, centred on the window with the
 * character behind it, and it stays there whenever it fits (0); a card too
 * wide to be centred there without reaching under a rail moves just far
 * enough to clear it.
 */
export function cardShift(windowWidth: number, left: number, right: number, card: number): number {
  const lo = left + THREAD_STAGE_MARGIN / 2;
  const hi = windowWidth - right - THREAD_STAGE_MARGIN / 2;
  const start = (windowWidth - card) / 2;
  if (start < lo) return lo - start;
  if (start + card > hi) return hi - (start + card);
  return 0;
}

/**
 * The size the frame's document is told (`data-width`), from the width the
 * card is really shown at, so a body styles for the room it has.
 */
export function shownCardSize(width: number): CardWidth {
  if (width <= CARD_SIZES.regular) return "regular";
  if (width <= CARD_SIZES.wide) return "wide";
  return "full";
}

/** What the stage is measured from: the window, and the docks beside it. */
export type StageMeasure = { windowWidth: number; left: number; right: number };

/**
 * Whether a card's edges ease from one measurement of the stage to the
 * next. Paging between widths, the host's re-decision on a revision and
 * the fold move them over one duration; the window or a dock moving does
 * not - the card follows the stage at once, or a card that no longer fits
 * would reach under a rail until the ease caught up.
 */
export function cardEdgesEase(before: StageMeasure, after: StageMeasure): boolean {
  return (
    before.windowWidth === after.windowWidth &&
    before.left === after.left &&
    before.right === after.right
  );
}
/**
 * Where a card's thread goes (cards-as-threads phase 1; the captain's C8
 * answer "A beside the card where it fits, C in place below that", with his
 * three tweaks). The arithmetic lives here, away from the DOM, because it
 * is the whole of the behaviour worth pinning - `threadGeometry.test.ts`
 * walks the R3.1 table at 960 / 1200 / 1440 / 1728 with both docks, one
 * dock and none.
 *
 * The ladder has three rungs and is walked in order:
 *
 *  1. **Beside the card**, in ONE container (tweak 1): one surface, one
 *     border, one radius, one shadow, a single hairline between the two
 *     columns, the pair centred on the stage as one object.
 *  2. **Fold the docks** (tweak 2). When the pair would leave the card
 *     under `CARD_MIN`, the docked rails give their width back - the stage
 *     becomes the whole window - and the pair is placed again. This is not
 *     today's collapse: a collapsed dock still holds its full rail width
 *     (`design/styles.css` counts any non-empty rail), so collapsing frees
 *     nothing. An edge tab says the panels are one click away.
 *  3. **In place.** The card's body becomes the thread, behind a segmented
 *     control in its head. It needs a stage under 720px, which the app's
 *     own 960px window minimum puts out of reach - it exists because the
 *     ladder must end somewhere, not because the app can get there.
 *
 * Tweak 3 - the reply box under the action row while there is no thread yet
 * - is the card's own footer and needs no arithmetic.
 */

/** The card's design width, the stack's own (`CARD_STACK_WIDTH`). */
export const THREAD_CARD_MAX = 560;
/** The air the stage keeps around the pair, total. */
export const THREAD_STAGE_MARGIN = 32;
/** The thread column: 40% of the stage, held between these. */
export const THREAD_MIN = 288;
export const THREAD_MAX = 360;
/** Below this the card is not a card any more, and the ladder takes its next rung. */
export const CARD_MIN = 400;

/** Where the thread sits, and what the pair measures. */
export type ThreadPlacement = {
  /** `beside` is rungs 1 and 2; `in-place` is rung 3. */
  home: "beside" | "in-place";
  /** The docked rails gave their width back so the pair could fit (rung 2). */
  folded: boolean;
  /** The card column's width in the pair. */
  card: number;
  /** The thread column's width; 0 when the thread is in place. */
  thread: number;
};

/** What the card measures with no thread open: what it asks for, inside the stage's margin. */
export function cardWidth(stage: number, cardMax: number = THREAD_CARD_MAX): number {
  return Math.min(cardMax, stage - THREAD_STAGE_MARGIN);
}

/** The pair inside a given stage, before any folding. */
function pairIn(stage: number, cardMax: number): { card: number; thread: number; fits: boolean } {
  const thread = Math.round(Math.min(THREAD_MAX, Math.max(THREAD_MIN, 0.4 * stage)));
  const card = Math.min(cardMax, stage - THREAD_STAGE_MARGIN - thread);
  return { card, thread, fits: card >= CARD_MIN };
}

/**
 * The ladder, for a window of `windowWidth` with `railsWidth` of docked
 * rails beside the stage. `railsWidth` is what the rails really occupy
 * (`--occupied-rail-left` + `--occupied-rail-right`), so a window with
 * nothing docked passes 0 and can never fold.
 *
 * `cardMax` is the width the card asks for (`requestedCardWidth`): 560 for
 * a regular card, more for a wide or full one or one the captain dragged.
 * The arithmetic is the same with it in place of 560; only the card column
 * grows, and only where the stage has the room.
 */
export function threadPlacement(
  windowWidth: number,
  railsWidth: number,
  cardMax: number = THREAD_CARD_MAX,
): ThreadPlacement {
  const stage = windowWidth - railsWidth;
  const docked = pairIn(stage, cardMax);
  if (docked.fits) {
    return { home: "beside", folded: false, card: docked.card, thread: docked.thread };
  }
  if (railsWidth > 0) {
    const whole = pairIn(windowWidth, cardMax);
    if (whole.fits) {
      return { home: "beside", folded: true, card: whole.card, thread: whole.thread };
    }
    // Even folded it does not fit: the thread goes in place, and the fold
    // stands - the whole window is what the in-place card has to read in,
    // and that is the narrowest rung of all (the prototype's own arithmetic).
    return { home: "in-place", folded: true, card: cardWidth(windowWidth, cardMax), thread: 0 };
  }
  return { home: "in-place", folded: false, card: cardWidth(stage, cardMax), thread: 0 };
}
import { useEffect, useState } from "react";

/**
 * What the shell measures for the thread ladder (cards-as-threads phase 1):
 * the window's width, and how much of it the DOCKED rails would take.
 *
 * "Would take" is the load-bearing word. While the docks are folded the
 * rails are still in the DOM with their panels in them - they are given
 * zero width by one CSS state, not unmounted - so `--rail-docked-left` and
 * `--rail-docked-right` keep saying what the rails ask for. Reading the
 * effective `--occupied-rail-*` instead would make the ladder circular:
 * folding would erase the reason to fold, and the pair would oscillate.
 */
export type ShellLayout = {
  windowWidth: number;
  /** `--rail-docked-left`, in px; 0 when nothing is docked on that side. */
  left: number;
  right: number;
  /** The two together: what the ladder subtracts from the window. */
  railsWidth: number;
};

function readPx(styles: CSSStyleDeclaration, name: string): number {
  const value = Number.parseFloat(styles.getPropertyValue(name));
  return Number.isFinite(value) ? value : 0;
}

export function readShellLayout(): ShellLayout {
  if (typeof window === "undefined" || typeof document === "undefined") {
    return { windowWidth: 0, left: 0, right: 0, railsWidth: 0 };
  }
  const styles = getComputedStyle(document.documentElement);
  const left = readPx(styles, "--rail-docked-left");
  const right = readPx(styles, "--rail-docked-right");
  return { windowWidth: window.innerWidth, left, right, railsWidth: left + right };
}

/**
 * The layout, re-measured on three signals: the window resizing, the STAGE
 * resizing (a rail docking, undocking, collapsing or folding is a change to
 * the stage's width and to nothing the caller renders), and every render of
 * the caller. The guard keeps an unchanged measurement from setting state,
 * so none of the three can loop - and the stage observer in particular
 * cannot, because folding changes the stage's width but not what this
 * reads.
 */
export function useShellLayout(): ShellLayout {
  const [layout, setLayout] = useState<ShellLayout>(readShellLayout);
  useEffect(() => {
    const measure = () => {
      const next = readShellLayout();
      setLayout((held) =>
        held.windowWidth === next.windowWidth &&
        held.left === next.left &&
        held.right === next.right
          ? held
          : next,
      );
    };
    measure();
    window.addEventListener("resize", measure);
    const stage = document.querySelector("[data-stage]");
    const observer = stage ? new ResizeObserver(measure) : undefined;
    if (stage && observer) observer.observe(stage);
    return () => {
      window.removeEventListener("resize", measure);
      observer?.disconnect();
    };
  });
  return layout;
}

