import { viewablePictures } from "@shared/cardPictures";
import type { CardWidth } from "@shared/cards";
import { isSafeCardHref } from "@shared/linkify";
import type { FrameAnswers, FramePicture } from "@shared/plugins/bridge";
import { FRAME_SANDBOX } from "@shared/plugins/containment";
import type { FrameMount, FrameTheme } from "@shared/plugins/frameDocument";
import { useEffect, useMemo, useRef, useState } from "react";
import { Button } from "../design";
import { useFrameController } from "../plugins/frames/FrameMount";
import type { FrameController, FrameMountSpec } from "../plugins/frames/frameController";
import {
  buildPrototypeSrcdoc,
  cardBodyHasScript,
  cardBodyHtml,
  cardStylesheet,
} from "./prototypeSrcdoc";

const MIN_BODY_HEIGHT = 48;

/**
 * Let the frame grow to its full document height. ResponseCard owns the
 * viewport constraint and scroll surface; capping the frame here gave long
 * bodies a second, nested scrollbar.
 */
export function cardBodyHeight(reported: number): number {
  return Math.max(MIN_BODY_HEIGHT, Math.ceil(reported));
}

type BodyProps = {
  body: string;
  theme: FrameTheme;
  title: string;
  /**
   * The action ids this body may raise over the bridge: its card's actions
   * minus the effect-bearing ones, which are the host chrome's alone
   * (`bridgeActionIds`).
   */
  declaredActionIds: string[];
  /** The size the card is shown at: the document's `data-width`. */
  width?: CardWidth;
  onAction: (actionId: string, value?: unknown) => void;
  /**
   * A picture in the body was clicked (card pictures, phase 3): its group's
   * pictures the viewer may show, which one, and the frame that opened
   * them, where focus returns when the viewer closes.
   */
  onPicture?: (
    set: { index: number; pictures: FramePicture[] },
    opener: HTMLIFrameElement | null,
  ) => void;
  /**
   * The body's own form (inline decisions, contract 4.22): the draft each
   * new document gets back by name, and every reading the bridge posts.
   */
  form?: FrameMountSpec["form"];
  /**
   * Filled with the frame's fresh reading of its form, for the footer click
   * that sends it; undefined when the frame cannot give one.
   */
  collectRef?: React.MutableRefObject<CollectAnswers | null>;
};

/** Asks the body's frame for a fresh reading of its form. */
export type CollectAnswers = () => Promise<FrameAnswers | undefined>;

const frameStyle = (height: number): React.CSSProperties => ({
  width: "100%",
  height,
  border: "none",
  display: "block",
  background: "transparent",
});

/**
 * Hosts agent-authored HTML - verbatim, there is no sanitizer - while the
 * card chrome stays in React, over the same bridge v2 controller every frame
 * uses: declared actions round back, links go to the host, height follows
 * the document.
 *
 * Two vehicles, one sandbox. A body without a script is data and rides
 * srcdoc, rebuilt when the body changes. A body carrying the agent's own
 * inline `<script>` (WI-16) is mounted: the host serves the same markup at a
 * card host of its own with each inline script's hash pinned into that
 * document's CSP, and the frame watchdog tears the frame down if a script
 * wedges it.
 */
export function HtmlCardBody(props: BodyProps) {
  // Keep the vertical inset outside the viewport whose height follows the
  // body. Inside it, a 100vh child plus padding reports viewport + padding
  // forever. Both vehicles share this inset; authored markup stays verbatim.
  return (
    <div style={{ paddingBlock: "var(--space-1)" }}>
      {cardBodyHasScript(props.body) ? (
        <ScriptedCardBody {...props} />
      ) : (
        <SrcdocCardBody {...props} />
      )}
    </div>
  );
}

function cardFrameSpec(
  props: BodyProps,
  frameRef: React.RefObject<HTMLIFrameElement | null>,
  setHeight: (height: number) => void,
  onUnresponsive?: () => void,
): FrameMountSpec {
  return {
    pluginId: "host",
    reads: [],
    actions: props.declaredActionIds,
    ...(props.width ? { width: props.width } : {}),
    onAction: (actionId, value) => props.onAction(actionId, value),
    onResize: (reported) => setHeight(cardBodyHeight(reported)),
    onLink: (href) => {
      if (isSafeCardHref(href)) {
        void window.firstmate.app.openExternal(href).catch(() => {});
      }
    },
    onImage: (index, pictures) => {
      const set = viewablePictures(index, pictures);
      if (set) props.onPicture?.(set, frameRef.current);
    },
    ...(props.form ? { form: props.form } : {}),
    ...(onUnresponsive ? { onUnresponsive } : {}),
  };
}

/** Points the card's collect handle at this frame's controller while it is mounted. */
function useCollect(
  collectRef: BodyProps["collectRef"],
  controllerRef: React.RefObject<FrameController | null>,
): void {
  useEffect(() => {
    if (!collectRef) return;
    const collect: CollectAnswers = () =>
      controllerRef.current?.collect() ?? Promise.resolve(undefined);
    collectRef.current = collect;
    return () => {
      if (collectRef.current === collect) collectRef.current = null;
    };
  }, [collectRef, controllerRef]);
}

function SrcdocCardBody(props: BodyProps) {
  const { body, theme, title } = props;
  const frameRef = useRef<HTMLIFrameElement>(null);
  const [height, setHeight] = useState(MIN_BODY_HEIGHT);
  const srcdoc = useMemo(() => buildPrototypeSrcdoc(body, theme), [body, theme]);

  const controllerRef = useFrameController(
    frameRef,
    cardFrameSpec(props, frameRef, setHeight),
    theme,
  );
  useCollect(props.collectRef, controllerRef);

  return (
    <iframe
      ref={frameRef}
      title={`${title} body`}
      sandbox={FRAME_SANDBOX}
      scrolling="no"
      srcDoc={srcdoc}
      style={frameStyle(height)}
    />
  );
}

type MountState =
  | { phase: "pending" }
  | { phase: "mounted"; mount: FrameMount }
  | { phase: "failed" }
  | { phase: "stopped" };

function ScriptedCardBody(props: BodyProps) {
  const { body, theme, title } = props;
  const frameRef = useRef<HTMLIFrameElement>(null);
  const [height, setHeight] = useState(MIN_BODY_HEIGHT);
  const [state, setState] = useState<MountState>({ phase: "pending" });
  // Bumped by Retry: the only way back from a stopped frame is a fresh mount.
  const [attempt, setAttempt] = useState(0);
  const mountIdRef = useRef<string | null>(null);
  const template = useMemo(() => ({ html: cardBodyHtml(body) }), [body]);

  // One mount per body (and per retry). The theme at mount time seeds the
  // served document; later themes are pushed over the bridge, not re-mounted.
  // biome-ignore lint/correctness/useExhaustiveDependencies: theme is pushed, not re-mounted; attempt is the retry trigger
  useEffect(() => {
    let active = true;
    let mountId: string | null = null;
    setState({ phase: "pending" });
    void window.firstmate.plugins
      .mountFrame({
        kind: "card",
        title,
        theme,
        style: cardStylesheet(),
        // The markup the agent wrote, unchanged. The host finds its inline
        // scripts and pins each one's hash into that mount's own CSP.
        template,
      })
      .then((mount) => {
        mountId = mount.mountId;
        if (active) {
          mountIdRef.current = mount.mountId;
          setState({ phase: "mounted", mount });
        } else {
          void window.firstmate.plugins.unmountFrame(mount.mountId).catch(() => {});
        }
      })
      .catch(() => {
        // The host refused the mount (its card cap); Retry asks again.
        if (active) setState({ phase: "failed" });
      });
    return () => {
      active = false;
      if (mountIdRef.current === mountId) mountIdRef.current = null;
      if (mountId) void window.firstmate.plugins.unmountFrame(mountId).catch(() => {});
    };
  }, [title, template, attempt]);

  const controllerRef = useFrameController(
    frameRef,
    cardFrameSpec(props, frameRef, setHeight, () => {
      // Removing the iframe detaches the wedged document; the browser reaps
      // its dedicated process. The served document goes with it.
      const mountId = mountIdRef.current;
      mountIdRef.current = null;
      if (mountId) void window.firstmate.plugins.unmountFrame(mountId).catch(() => {});
      setState({ phase: "stopped" });
    }),
    theme,
    state.phase === "mounted" ? state.mount.url : undefined,
  );
  useCollect(props.collectRef, controllerRef);

  if (state.phase === "stopped" || state.phase === "failed") {
    return (
      <div
        data-card-body-stopped=""
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: "var(--space-3)",
          minHeight: MIN_BODY_HEIGHT,
        }}
      >
        <p style={{ margin: 0, color: "var(--fg-3)", fontSize: "var(--text-sm)" }}>
          {state.phase === "stopped"
            ? "This card stopped responding."
            : "This card could not be opened."}
        </p>
        <Button variant="secondary" size="sm" onClick={() => setAttempt((n) => n + 1)}>
          Retry
        </Button>
      </div>
    );
  }
  if (state.phase === "pending") return <div data-frame-mount-pending="" style={{ height }} />;
  return (
    <iframe
      ref={frameRef}
      title={`${title} body`}
      sandbox={FRAME_SANDBOX}
      scrolling="no"
      src={state.mount.url}
      data-frame-mount={state.mount.mountId}
      style={frameStyle(height)}
    />
  );
}

/** Kept as a compatibility alias for callers outside the renderer bundle. */
export const PrototypeBody = HtmlCardBody;
import { isSafeCardHref, splitCardBodyUrls } from "@shared/linkify";
import { FRAME_CSP } from "@shared/plugins/containment";
import { buildFrameDocument, type FrameTheme } from "@shared/plugins/frameDocument";
import { frameStylesheet } from "../plugins/frames/frameStylesheet";

/**
 * A card body is agent-authored HTML, rendered VERBATIM inside an
 * opaque-origin frame. There is no sanitizer (captain decision, 2026-09-15,
 * direction C; `docs/live-prototype-security.md`): the boundary is the
 * `<iframe sandbox="allow-scripts">`, the frame CSP (`default-src 'none'`,
 * every script by hash), and the host's validation of every bridge message.
 * The audit measured that boundary against the whole attack corpus with no
 * sanitizer at all and nothing executed, nothing loaded, nothing left the
 * machine; the allowlists only ever degraded honest markup.
 *
 * Two vehicles, one policy. A body with no `<script>` is data and rides
 * srcdoc under the document this builds, whose CSP pins the bridge alone -
 * so a `<script>` that arrived some other way still cannot run. A body that
 * carries its own inline script takes the mount path instead
 * (`PrototypeBody.tsx`), where the host hashes each script and serves the
 * markup unchanged (`src/main/frames/frameMounts.ts`).
 */
export const PROTOTYPE_FRAME_CSP = FRAME_CSP;

/** Whether a body asks for the mount path: it carries a `<script>` element. */
export function cardBodyHasScript(body: string): boolean {
  return /<script[\s>/]/i.test(body);
}

/**
 * The body as markup. A body with no tags at all is legacy plain text -
 * early cards and a few backends still write it - so it becomes paragraphs
 * with its safe URLs linked; anything else is the author's own document.
 */
export function cardBodyHtml(body: string): string {
  return /<[a-z][\s\S]*>/i.test(body) ? body : plainTextBody(body);
}

function escapeHtml(text: string): string {
  return text
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function plainTextBody(text: string): string {
  const linked = splitCardBodyUrls(text)
    .map((part) => {
      const escaped = escapeHtml(part.value);
      return part.type === "url" && isSafeCardHref(part.value)
        ? `<a href="${escaped}">${escaped}</a>`
        : escaped;
    })
    .join("");
  return linked
    .split(/\n{2,}/)
    .map((paragraph) => `<p>${paragraph.replaceAll("\n", "<br>")}</p>`)
    .join("");
}

export function buildPrototypeSrcdoc(body: string, theme: FrameTheme): string {
  return buildFrameDocument({
    csp: PROTOTYPE_FRAME_CSP,
    theme,
    style: cardStylesheet(),
    html: cardBodyHtml(body),
  });
}

/**
 * The measure a card body keeps in any width (the captain's Q7 A of
 * 2026-09-28): prose - paragraphs, lists, headings, captions, summaries -
 * holds a 66-character line, while tables, code, picture groups and figures
 * take the room a wide card gives them. In the usual 510 px column 66
 * characters is wider than the column, so a regular card reads as before.
 * A card's own rule, never a template's: panels and plugin frames lay out
 * their own measure.
 */
export const CARD_MEASURE_STYLE = `
  /* HtmlCardBody owns the vertical inset outside this auto-sized viewport.
     flow-root keeps child margins in the measured body without padding. */
  body { padding-block: 0; display: flow-root; }
  :is(p, ul, ol, dl, blockquote, h1, h2, h3, h4, h5, h6, figcaption, summary) { max-width: 66ch; }
  /* A group's caption is its own line under the strip (flex-basis 100%): a
     narrower box would let it rise beside the thumbnails, so the line keeps
     the group's width and its text keeps the measure. */
  .fm-pictures > figcaption { max-width: none; padding-right: max(0px, calc(100% - 66ch)); }
`;

let cardStyle: string | undefined;

/** The design system's stylesheet and the card's measure; a body's own `<style>` rides its markup. */
export function cardStylesheet(): string {
  cardStyle ??= `${frameStylesheet()}\n${CARD_MEASURE_STYLE}`;
  return cardStyle;
}

