import type React from "react";
import { useEffect, useReducer } from "react";
import { FIRST_TURN_LABEL, firstTurnLabelNextChange, firstTurnLabelPhase } from "./firstTurn";
import { useShellStore } from "./store";
import "./firstTurnLabel.css";

/**
 * "Thinking…" just above the character while the Firstmate handles the
 * captain's first turn (docs/first-launch.md "The first turn's label"). The
 * record it reads is the store's `firstTurn`, armed by the first send and
 * moved by the Firstmate's own busy signal; ./firstTurn decides the
 * phase, and this component only re-reads it at the moments the clock can
 * change it. It mounts one line inside the character's centred frame, so it
 * dims and blurs with the character when a card takes the stage.
 */
export function FirstTurnLabel() {
  const record = useShellStore((s) => s.firstTurn);
  const [, tick] = useReducer((n: number) => n + 1, 0);
  const phase = firstTurnLabelPhase(record, Date.now());
  useEffect(() => {
    // Re-read at the next moment the clock can move the phase; each tick
    // renders the new phase, which schedules the one after it.
    if (phase === "absent") return;
    const next = firstTurnLabelNextChange(record, Date.now());
    if (next === null) return;
    const id = window.setTimeout(tick, Math.max(0, next - Date.now()) + 1);
    return () => window.clearTimeout(id);
  }, [record, phase]);
