    <div
      className="fm-first-turn-label"
      data-first-turn-label=""
      data-on={shown ? "true" : "false"}
      aria-hidden={!shown}
      style={style}
    >
      {FIRST_TURN_LABEL.text}
    </div>
  );
}
/**
 * The first turn's label (captain's call of 2026-09-30 on the reviewed
 * prototype, task FI3-298; docs/first-launch.md "The first turn's label"):
 * a small "Thinking…" just above the character while the Firstmate handles
 * the captain's FIRST turn, so a new user reads the working animation as
 * work. It rides the first-run record (`firstTurnAt`, src/shared/firstRun.ts):
 * the turn sent while that stamp is still null is the first, and the label
 * never returns. It follows the Firstmate's own busy signal, never a clock
 * of its own guessing: it never shows before the turn has started, and it
 * leaves as the turn ends. Nothing here is progress - no count, no fill, no
 * time left.
 *
 * DOM-free and time-injected, like the character machine.
 */
export const FIRST_TURN_LABEL = {
  text: "Thinking…",
  /** Shows this long after the send, so a quick answer never flashes it. */
  showAfterMs: 300,
  /** Once shown, stays at least this long, so a short turn never blinks it. */
  minShownMs: 900,
  /** The fade in is the design system's --dur-med; the fade out its --dur-slow. */
  fadeInMs: 360,
  fadeOutMs: 700,
  /**
   * Its bottom edge sits this far above the character's centre: the
   * structure's nominal outline (0.36 of the 300 px home-screen character)
   * plus a 10 px gap.
   */
  risePx: 118,
} as const;

export type FirstTurnRecord = {
  /** When the captain's first turn was sent. */
  sentAt: number;
  /** When the Firstmate's turn began (its busy signal rose); null until it has. */
  startedAt: number | null;
  /** When that turn ended (busy fell); null while it runs. */
  endedAt: number | null;
};

/**
 * The record after a `firstmate_state` event. A rise starts the turn once;
 * a fall ends it only after it began, so a wake ending before the captain's
 * turn is served does not end it, and a later rise never restarts it.
 */
export function firstTurnAfterBusy(
  record: FirstTurnRecord | null,
  busy: boolean,
  now: number,
): FirstTurnRecord | null {
  if (!record) return record;
  if (busy) return record.startedAt === null ? { ...record, startedAt: now } : record;
  return record.startedAt !== null && record.endedAt === null
    ? { ...record, endedAt: now }
    : record;
}

/** When the label shows: the send delay, but never before the turn has started. */
export function firstTurnLabelShowsAt(record: FirstTurnRecord): number | null {
  if (record.startedAt === null) return null;
  return Math.max(record.sentAt + FIRST_TURN_LABEL.showAfterMs, record.startedAt);
}

/**
 * When the label starts leaving: the turn's end, held to the minimum shown.
 * Null while the turn runs, and when it never showed - a turn over before
 * the label was due shows nothing at all.
 */
export function firstTurnLabelLeavesAt(record: FirstTurnRecord): number | null {
  const showsAt = firstTurnLabelShowsAt(record);
  if (showsAt === null || record.endedAt === null || record.endedAt <= showsAt) return null;
  return Math.max(record.endedAt, showsAt + FIRST_TURN_LABEL.minShownMs);
}

export type FirstTurnLabelPhase =
  /** Nothing on the stage: no first turn under way, or its label is over. */
  | "absent"
  /** Mounted and invisible: the turn is sent or running but the label is not due yet. */
  | "pending"
  | "shown"
  /** Fading out. */
  | "leaving";

export function firstTurnLabelPhase(
  record: FirstTurnRecord | null,
  now: number,
): FirstTurnLabelPhase {
  if (!record) return "absent";
  const showsAt = firstTurnLabelShowsAt(record);
  if (showsAt === null) return record.endedAt === null ? "pending" : "absent";
  if (record.endedAt !== null && record.endedAt <= showsAt) return "absent";
  if (now < showsAt) return "pending";
  const leavesAt = firstTurnLabelLeavesAt(record);
  if (leavesAt === null || now < leavesAt) return "shown";
  return now < leavesAt + FIRST_TURN_LABEL.fadeOutMs ? "leaving" : "absent";
}

/**
 * The next moment the phase can change on the clock alone, or null when
 * only an event (the turn starting or ending) can change it.
 */
export function firstTurnLabelNextChange(
  record: FirstTurnRecord | null,
  now: number,
): number | null {
  if (!record) return null;
  const showsAt = firstTurnLabelShowsAt(record);
  if (showsAt === null) return null;
  if (record.endedAt !== null && record.endedAt <= showsAt) return null;
  if (now < showsAt) return showsAt;
  const leavesAt = firstTurnLabelLeavesAt(record);
  if (leavesAt === null) return null;
  if (now < leavesAt) return leavesAt;
  const goneAt = leavesAt + FIRST_TURN_LABEL.fadeOutMs;
  return now < goneAt ? goneAt : null;
}

