import { z } from "zod";
import type { RecordAnchor } from "../../../app/store";
import { anchorInWindow } from "../../../cards/paneGeometry";

/**
 * The now panel's two gestures (task-system design section 10, P4). Both are
 * POINTING, never writes, and what each means is the host's decision, made
 * here against the shell.
 *
 * - `open`: a row was clicked.
 *   - a row waiting on you names the decision card it waits for; when that
 *     card is still on the stack it comes to the front (the captain answers
 *     there, as before);
 *   - otherwise the task's record opens as the pane docked beside
 *     the rail, anchored to the row that opened it, and while it is open
 *     every turn carries the task as its hint.
 * - `point`: the open pane's row MOVED - the panel scrolled, or the frame
 *   resized under it. The pane holds its place and re-aims its tie; a report
 *   with a null anchor means the row has left the panel's own viewport, so
 *   the tie drops rather than pointing at nothing.
 *
 * A row's box is measured inside the frame, in the frame's own viewport, so
 * the host adds the iframe's offset (`anchorInWindow`): only the host knows
 * where the frame sits in the window. Values cross the frame boundary, so
 * they are parsed here like any other input: a malformed one is refused as a
 * bridge error and nothing happens.
 */
const anchorSchema = z
  .strictObject({
    top: z.number().finite(),
    height: z.number().finite().nonnegative(),
  })
  .nullable();

export const nowOpenValueSchema = z.strictObject({
  taskId: z.string().min(1).max(64),
  cardId: z.string().min(1).max(128).optional(),
  anchor: anchorSchema.optional(),
});
export type NowOpenValue = z.infer<typeof nowOpenValueSchema>;

export const nowPointValueSchema = z.strictObject({
  taskId: z.string().min(1).max(64),
  anchor: anchorSchema,
});
export type NowPointValue = z.infer<typeof nowPointValueSchema>;

/** What the host must offer for the gestures to land. */
export type NowOpenTarget = {
  /** Brings a stacked card to the front; false when it is not on the stack. */
  focusCard: (cardId: string) => boolean;
  openRecord: (taskId: string, anchor?: RecordAnchor | null) => void;
  pointRecord: (taskId: string, anchor: RecordAnchor | null) => void;
};

export type NowOpenOutcome = "card" | "record";

export function openFromNow(
  value: unknown,
  target: NowOpenTarget,
  frame?: DOMRect,
): NowOpenOutcome {
  const parsed = nowOpenValueSchema.safeParse(value);
  if (!parsed.success) throw new Error(`open: ${parsed.error.message}`);
  const { taskId, cardId, anchor } = parsed.data;
  if (cardId && target.focusCard(cardId)) return "card";
  target.openRecord(taskId, anchorInWindow(anchor ?? null, frame));
  return "record";
}

export function pointFromNow(value: unknown, target: NowOpenTarget, frame?: DOMRect): void {
  const parsed = nowPointValueSchema.safeParse(value);
  if (!parsed.success) throw new Error(`point: ${parsed.error.message}`);
  const { taskId, anchor } = parsed.data;
  target.pointRecord(taskId, anchorInWindow(anchor, frame));
}
