    },
  },
  sidePanels: {
    activity: sidePanelBinding({
      framePanel: activityPanel,
      Compact: ActivityCompact,
      source: createReadPanelSource(appReadExecutor, "feed.recent", {}, (lines: FeedLine[]) => ({
        lastAt: lines.at(-1)?.at ?? null,
      })),
    }),
    now: sidePanelBinding({
      framePanel: tasksPanel,
      Compact: NowCompact,
      HeaderAction: NowHeaderFilter,
      source: createReadPanelSource(appReadExecutor, "tasks.board", {}, (board) =>
        nowPanelHasRows(board) ? nowCompactCounts(board) : null,
      ),
      // One object per selected row, so the push fires on a change and not
      // on every render of the rail.
      useFrameState: () => {
        const selectedTaskId = useShellStore((s) => s.record?.taskId ?? null);
        return useMemo(() => ({ selectedTaskId }), [selectedTaskId]);
      },
      actions: {
        open: async (value, frame) => {
          const parsed = nowOpenValueSchema.parse(value);
          // An explicit record gesture has no shortcut; preserve that route.
          if (!parsed.cardId) {
            openFromNow(parsed, useShellStore.getState(), frame);
            return;
          }
          // The shortcut may have aged since the frame painted it. Refresh
          // associations, then reconcile with the focusable local stack.
          const detail = await window.firstmate.tasks.detail(parsed.taskId);
          const shell = useShellStore.getState();
          const { waitingCardId } = presentTask(detail, shell.cards);
          openFromNow({ ...parsed, cardId: waitingCardId ?? undefined }, shell, frame);
        },
        point: (value, frame) => {
          pointFromNow(value, useShellStore.getState(), frame);
        },
      },
    }),
  },
};

export function registerBuiltinPlugin(host: PluginHost): () => void {
  return host.registerPlugin(builtinManifest, builtinBindings, { firstParty: true });
