    background: var(--bg-1); border: 1px solid var(--line-1); border-radius: var(--radius-s);
    cursor: zoom-in;
  }
  .fm-pictures > figcaption { order: 1; flex: 0 0 100%; margin: 0 0 var(--space-2); }
