import { isSafeCardHref } from "@shared/linkify";
import { taskStatusWord } from "@shared/nowPanel";
import type { FrameTheme } from "@shared/plugins/frameDocument";
import type { TaskDetail } from "@shared/tasks";
import { useEffect, useMemo, useState } from "react";
import { ResponseCard } from "../design";
import { recordTemplate } from "../plugins/builtin";
import { BUILTIN_PLUGIN_ID } from "../plugins/builtin/manifest";
import { FrameMount } from "../plugins/frames/FrameMount";
import { pluginHost, useCardKind } from "../plugins/host";
import { appReadExecutor } from "../plugins/reads/appExecutor";

/** The wire-less kind the built-in manifest dresses the record with. */
export const RECORD_CARD_KIND = "task-record";
/** The body follows its document's height up to this, then scrolls inside. */
const MAX_BODY_HEIGHT = 420;
const MIN_BODY_HEIGHT = 48;

/**
 * The task-record card (task-system design section 10, P4): one task,
 * read-only, opened from a now-panel row. The chrome is the host's - kind
 * chip "Task", the title, a meta line of key and state, and close, which is
 * its ONLY control (captain's call: no buttons, every write happens by
 * talking to Firstmate while the card is open). The body is the record
 * template in the frame vehicle, fed by `tasks.detail` over the bridge;
 * the chrome subscribes to the same read for the title and the meta line,
 * so a state change re-titles the card the moment the record changes.
 *
 * Never persisted, never agent-emitted, never a feed line: closing it is a
 * shell-only act that reveals the character.
 */
export function RecordCard({
  taskId,
  theme,
  onClose,
}: {
  taskId: string;
  theme: FrameTheme;
  onClose: () => void;
}) {
  const kind = useCardKind(RECORD_CARD_KIND);
  const [detail, setDetail] = useState<TaskDetail | null>(null);
  const [unreadable, setUnreadable] = useState(false);
  const template = useMemo(() => recordTemplate(taskId), [taskId]);

  useEffect(() => {
    setDetail(null);
    setUnreadable(false);
    return appReadExecutor().subscribe(
      "tasks.detail",
      { id: taskId },
      {
        onValue: (value) => setDetail(value as TaskDetail),
        onError: () => setUnreadable(true),
      },
    );
  }, [taskId]);

  const meta = detail
    ? `${detail.key} · ${taskStatusWord(detail)}`
    : unreadable
      ? "this record could not be read"
      : "";

  return (
    <ResponseCard
      kind={kind.chrome}
      title={detail?.title ?? ""}
      meta={meta}
      width="100%"
      onClose={onClose}
    >
      <div data-record-card={taskId}>
        <FrameMount
          title="Task record body"
          template={template}
          spec={{
            pluginId: BUILTIN_PLUGIN_ID,
            reads: pluginHost.declaredReads(BUILTIN_PLUGIN_ID),
            actions: [],
            onAction: () => {},
            onLink: (href) => {
              if (isSafeCardHref(href)) {
                void window.firstmate.app.openExternal(href).catch(() => {});
              }
            },
          }}
          theme={theme}
          layout="auto"
          minAutoHeight={MIN_BODY_HEIGHT}
          maxAutoHeight={MAX_BODY_HEIGHT}
        />
      </div>
    </ResponseCard>
  );
}

