describe("the task-record pane beside the now panel (task-system P4)", () => {
  const anchor = { top: 300, height: 26 };
  afterEach(() => {
    useShellStore.setState({ cards: [], record: null, cardIndex: 0, recording: false });
  });

  it("is not on the stack: an open pane changes neither the pager nor the phase", () => {
    const note = card({ id: "n1", status: "ready", body: "a" });
    useShellStore.setState({ cards: [note], cardIndex: 0 });
    useShellStore.getState().openRecord("t1", anchor);
    expect(useShellStore.getState()).toMatchObject({
      record: { taskId: "t1", anchor },
      cardIndex: 0,
    });
    // The pane lives in the rail's gutter, so it never claims the stage:
    // the phase is the cards' business alone.
    expect(derivePhase(false, [], false)).toBe("idle");
    expect(visibleCards(useShellStore.getState().cards)).toHaveLength(1);
    // The pager spans the cards only, so it cannot page onto the pane.
    useShellStore.getState().nextCard();
    expect(useShellStore.getState().cardIndex).toBe(0);
  });

  it("opens with no anchor when the row never reported one", () => {
    useShellStore.getState().openRecord("t1");
    expect(useShellStore.getState().record).toEqual({ taskId: "t1", anchor: null });
  });

  it("re-aims at its row, ignores a stale report, and holds still for an identical one", () => {
    useShellStore.getState().openRecord("t1", anchor);
    const moved = { top: 240, height: 26 };
    useShellStore.getState().pointRecord("t1", moved);
    expect(useShellStore.getState().record).toEqual({ taskId: "t1", anchor: moved });
    // The row scrolled out of the panel's viewport: the pane unties.
    useShellStore.getState().pointRecord("t1", null);
    expect(useShellStore.getState().record).toEqual({ taskId: "t1", anchor: null });
    // A report for another task is stale and leaves the pane alone.
    useShellStore.getState().pointRecord("t2", moved);
    expect(useShellStore.getState().record).toEqual({ taskId: "t1", anchor: null });
    // An identical report is the same object back: no re-render, no re-push.
    useShellStore.getState().pointRecord("t1", moved);
    const held = useShellStore.getState().record;
    useShellStore.getState().pointRecord("t1", { ...moved });
    expect(useShellStore.getState().record).toBe(held);
  });

  it("stays open when a card comes to the front, and re-points at another task", () => {
    const one = card({ id: "c1", status: "ready", body: "a" });
    const two = card({ id: "c2", status: "ready", actions: DECIDE, body: "b" });
    useShellStore.setState({ cards: [one, two], cardIndex: 0 });
    useShellStore.getState().openRecord("t1", anchor);
    // A decision card brought forward from the panel is not the pane's
    // business: both are on screen, so both stay.
    expect(useShellStore.getState().focusCard("c2")).toBe(true);
    expect(useShellStore.getState()).toMatchObject({
      record: { taskId: "t1" },
      cardIndex: 1,
    });
    expect(useShellStore.getState().focusCard("gone")).toBe(false);
    // Clicking another row swaps what the pane shows.
    useShellStore.getState().openRecord("t2", { top: 90, height: 26 });
    expect(useShellStore.getState().record).toEqual({
      taskId: "t2",
      anchor: { top: 90, height: 26 },
    });
  });

  it("takes focus back when it closes, once", () => {
    useShellStore.getState().openRecord("t1", anchor);
    const before = useShellStore.getState().focusRequest;
