export type WindowSize = { width: number; height: number };

/** The narrowest window the app allows, read off the window itself. */
export function minimumWindowSize(app: ElectronApplication): Promise<WindowSize> {
  return app.evaluate(({ BrowserWindow }) => {
    const [window] = BrowserWindow.getAllWindows();
    if (!window) throw new Error("App window missing");
    const [width = 0, height = 0] = window.getMinimumSize();
    return { width, height };
  });
}

/**
 * Resizes the app's window and waits until the page lays out at that size.
 * Returns the size it had, for a spec to put back.
 */
export async function resizeWindow(
  app: ElectronApplication,
  page: Page,
  size: WindowSize,
): Promise<WindowSize> {
  const before = await app.evaluate(({ BrowserWindow }, next) => {
    const [window] = BrowserWindow.getAllWindows();
    if (!window) throw new Error("App window missing");
    const [width = 0, height = 0] = window.getSize();
    window.setSize(next.width, next.height);
    return { width, height };
  }, size);
  await expect
    .poll(() => page.evaluate(() => ({ width: window.innerWidth, height: window.innerHeight })))
    .toEqual(size);
  return before;
}

