    const frame = document.querySelector("[data-crew-formation]")?.parentElement;
    if (frame) {
      frame.style.opacity = "";
      frame.style.filter = "";
      frame.style.transition = "";
    }
  });
  await page.waitForTimeout(900);
  await page.screenshot({ path: join(OUT, "light-acrylic-today.png") });
});
