import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { expect, test } from "@playwright/test";
import { CardStore } from "../../src/core/storage/cardStore";
import { openDatabase } from "../../src/core/storage/db";
import { seedTask } from "../../src/core/tasks/seedTask";
import { TaskService } from "../../src/core/tasks/taskService";
import type { Card } from "../../src/shared/cards";
import { scratchDir } from "../helpers/scratchDirs";
import { type LaunchedApp, launchApp } from "./launch";
import { resizeWindow } from "./layout";
import { expandDock, nowRow } from "./rails";
import { setThemeViaSettings } from "./theme";

// Scratch probe, never committed: the same scene as the hidden-window probe,
// in a SHOWN translucent window (scratch env FM3000_SCRATCH_SHOW), read back
// through the app's own compositor (capturePage), alpha kept.

const OUT = join(process.cwd(), "artifacts", "solid-cards-plan", "raw");
const NOTE_BODY = `
<p>The plan card's body, as a crewmate would write it: a sentence, then a figure.</p>
<figure aria-label="A sample figure in theme tokens">
<svg viewBox="0 0 510 96" width="100%" role="img">
  <rect x="0.5" y="0.5" width="240" height="95" rx="12" fill="var(--bg-1)" stroke="var(--line-1)"/>
  <rect x="269.5" y="0.5" width="240" height="95" rx="12" fill="var(--accent-dim)" stroke="var(--accent)"/>
  <text x="14" y="30" fill="var(--fg-1)" font-size="14">Before</text>
  <text x="283" y="30" fill="var(--fg-1)" font-size="14">After</text>
  <text x="14" y="58" fill="var(--fg-2)">acrylic, 6% white</text>
  <text x="283" y="58" fill="var(--fg-2)">solid, the raised surface</text>
  <text x="14" y="82" fill="var(--fg-3)" font-family="var(--font-mono)" font-size="11">--acrylic-bg</text>
  <text x="283" y="82" fill="var(--fg-3)" font-family="var(--font-mono)" font-size="11">--bg-2</text>
</svg>
</figure>
<p>Press <kbd>Esc</kbd> to hide a record; <mark>nothing is written</mark>.</p>
<table><thead><tr><th>Surface</th><th>Today</th><th>Proposed</th></tr></thead>
<tbody><tr><td>Card</td><td>acrylic</td><td>solid</td></tr><tr><td>Record</td><td>pane</td><td>card</td></tr></tbody></table>
<details><summary>Evidence a reader may skip</summary><p>A details panel on the solid surface.</p></details>
`;

function seeded(): string {
  const userDataDir = scratchDir("fm3000-solid-cards-shown-");
  const db = openDatabase(userDataDir);
  const tasks = new TaskService({ db, strict: true });
  const dir = join(userDataDir, "crew", "sc-task");
  mkdirSync(dir, { recursive: true });
  seedTask(tasks, {
    id: "sc-task",
    title: "Chart the harbour",
    intent: { goal: "Chart the harbour.", userWords: "chart the harbour" },
    status: "idle",
    worktreeDir: dir,
    model: { provider: "fm-mock", id: "mock-1" },
    outcome: "Two channels look deep enough. Nothing needs you.",
    createdAt: Date.now() - 60_000,
  });
  const cards = new CardStore(db);
  cards.upsert({
    id: "card-sc-decision",
    author: "crewmate",
    priority: 30,
    meta: "crewmate 40",
    title: "Two ways to frost the record",
    model: "Claude Fable 5.1",
    body: NOTE_BODY,
    actions: [
      { id: "pane", label: "Keep the pane", variant: "secondary" },
      { id: "stack", label: "Put it in the stack", variant: "primary", default: true },
    ],
    status: "ready",
    createdAt: Date.now() - 30_000,
  } as Card);
  db.close();
  return userDataDir;
}

const SOLID_STYLE = `
:root, [data-theme="light"] {
  --acrylic-bg: var(--bg-2);
  --acrylic-blur: none;
  --acrylic-border: var(--line-1);
}`;

let launched: LaunchedApp;

async function capture(name: string): Promise<void> {
  const b64: string = await launched.app.evaluate(async ({ BrowserWindow }) => {
    const [win] = BrowserWindow.getAllWindows();
    if (!win) throw new Error("no window");
    const image = await win.webContents.capturePage();
    return image.toPNG().toString("base64");
  });
  writeFileSync(join(OUT, name), Buffer.from(b64, "base64"));
}

test.beforeAll(async () => {
  mkdirSync(OUT, { recursive: true });
  launched = await launchApp({
    userDataDir: seeded(),
    withMockProvider: true,
    env: { FM3000_SCRATCH_SHOW: "1" },
  });
  await resizeWindow(launched.app, launched.page, { width: 1200, height: 800 });
});

test.afterAll(async () => {
  await launched.close();
});

test("captures in a shown translucent window", async () => {
  const { page } = launched;
  expect(await page.evaluate(() => document.documentElement.dataset.windowMaterial)).toBe("translucent");
  await expect(page.locator("[data-card-layer]")).toBeVisible();
  await expect(page.frameLocator('iframe[title="Two ways to frost the record body"]').locator("table")).toBeVisible();
  await page.waitForTimeout(1500);
  await capture("dark-acrylic-today.png");

  await expandDock(page, "now");
  const key = (await page.evaluate(async () => (await window.firstmate.tasks.board()).tasks[0]?.key)) ?? "";
  await nowRow(page, key).evaluate((el) => (el as HTMLElement).click());
  await expect(page.locator("[data-record-pane]")).toHaveCSS("opacity", "1");
  await page.waitForTimeout(800);
  await capture("dark-record-pane-today.png");
  await page.keyboard.press("Escape");
  await expect(page.locator("[data-record-pane]")).toHaveCount(0);

  await page.evaluate((css) => {
    const style = document.createElement("style");
    style.id = "scratch-solid";
    style.textContent = css;
    document.head.append(style);
    const frame = document.querySelector("[data-crew-formation]")?.parentElement;
    if (frame) {
      frame.style.transition = "opacity 700ms cubic-bezier(0.16,1,0.3,1)";
      frame.style.filter = "none";
      frame.style.opacity = "0";
    }
  }, SOLID_STYLE);
  await page.waitForTimeout(900);
  await capture("dark-solid-proposed.png");

  await setThemeViaSettings(page, "light");
  await page.waitForTimeout(900);
  await capture("light-solid-proposed.png");

  await page.evaluate(() => {
    document.getElementById("scratch-solid")?.remove();
    const frame = document.querySelector("[data-crew-formation]")?.parentElement;
    if (frame) {
      frame.style.opacity = "";
      frame.style.filter = "";
      frame.style.transition = "";
    }
  });
  await page.waitForTimeout(900);
  await capture("light-acrylic-today.png");
});
EOF
